            }
            Expr::Field { object, field } => {
                format!("{}.{}", object.to_ast_string(indent), field)
            }
            Expr::MethodCall { object, method, args } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_ast_string(indent)).collect();
                format!("{}.{}({})", object.to_ast_string(indent), method, arg_strs.join(", "))
            }
            Expr::Index { object, index } => {
                format!("{}[{}]", object.to_ast_string(indent), index.to_ast_string(indent))
            }
            Expr::If { cond, then_block, else_block } => {
                let mut s = format!("if {} then\n", cond.to_ast_string(indent));
