{"command":"cat << 'EOF' > src/analyzer.rs
use std::collections::HashSet;
use crate::ast::*;

#[derive(Debug, Clone)]
pub struct AnalysisError {
    pub line: usize,
    pub column: usize,
    pub message: String,
}

pub struct Analyzer {
    scopes: Vec<HashSet<String>>,
    in_func: bool,
    in_loop: bool,
    pub errors: Vec<AnalysisError>,
}

impl Analyzer {
    pub fn new() -> Self {
        let mut global_scope = HashSet::new();
        global_scope.insert("std".to_string());
        Self {
            scopes: vec![global_scope],
            in_func: false,
            in_loop: false,
            errors: Vec::new(),
        }
    }

    fn push_scope(&mut self) {
        self.scopes.push(HashSet::new());
    }

    fn pop_scope(&mut self) {
        self.scopes.pop();
    }

    fn declare_var(&mut self, name: &str, line: usize, col: usize) {
        if let Some(current_scope) = self.scopes.last_mut() {
            if current_scope.contains(name) {
                self.errors.push(AnalysisError {
                    line,
                    column: col,
                    message: format!("duplicate variable '{}'", name),
                });
            } else {
                current_scope.insert(name.to_string());
            }
        }
    }

    fn check_var(&mut self, name: &str, line: usize, col: usize) {
        for scope in self.scopes.iter().rev() {
            if scope.contains(name) {
                return;
            }
        }
        self.errors.push(AnalysisError {
            line,
            column: col,
            message: format!("undeclared variable '{}'", name),
        });
    }

    pub fn analyze_program(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            self.analyze_stmt(stmt);
        }
    }

    pub fn analyze_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let { name, init } => {
                if let Some(expr) = init {
                    self.analyze_expr(expr);
                }
                self.declare_var(name, 1, 0); // location approximated if needed
            }
            Stmt::Assign { target, value } => {
                self.analyze_expr(value);
                match target {
                    AssignTarget::Var(n) => self.check_var(n, 1, 0),
                    AssignTarget::Field { object, .. } => self.analyze_expr(object),
                    AssignTarget::Index { object, index } => {
                        self.analyze_expr(object);
                        self.analyze_expr(index);
                    }
                }
            }
            Stmt::If { cond, then_block, else_block } => {
                self.analyze_expr(cond);
                self.push_scope();
                for s in then_block { self.analyze_stmt(s); }
                self.pop_scope();

                if let Some(eb) = else_block {
                    self.push_scope();
                    for s in eb { self.analyze_stmt(s); }
                    self.pop_scope();
                }
            }
            Stmt::While { cond, body } => {
                self.analyze_expr(cond);
                let old_loop = self.in_loop;
                self.in_loop = true;
                self.push_scope();
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
                self.in_loop = old_loop;
            }
            Stmt::For { var, iter, body } => {
                self.analyze_expr(iter);
                let old_loop = self.in_loop;
                self.in_loop = true;
                self.push_scope();
                self.declare_var(var, 1, 0);
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
                self.in_loop = old_loop;
            }
            Stmt::Break => {
                if !self.in_loop {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "break statement outside loop".to_string(),
                    });
                }
            }
            Stmt::Return(opt_expr) => {
                if !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "return statement outside function".to_string(),
                    });
                }
                if let Some(expr) = opt_expr {
                    self.analyze_expr(expr);
                }
            }
            Stmt::Expr(expr) => self.analyze_expr(expr),
        }
    }

    pub fn analyze_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Literal(_) => {}
            Expr::Var(name) => self.check_var(name, 1, 0),
            Expr::SelfKw => {
                if !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "self keyword outside function".to_string(),
                    });
                }
            }
            Expr::Array(items) => {
                for item in items { self.analyze_expr(item); }
            }
            Expr::Dict(entries) => {
                for (_, v) in entries { self.analyze_expr(v); }
            }
            Expr::Func { params, body } => {
                let old_func = self.in_func;
                let old_loop = self.in_loop;
                self.in_func = true;
                self.in_loop = false;

                self.push_scope();
                for p in params {
                    self.declare_var(p, 1, 0);
                }
                for s in body {
                    self.analyze_stmt(s);
                }
                self.pop_scope();

                self.in_func = old_func;
                self.in_loop = old_loop;
            }
            Expr::Unary { op, expr } => {
                if matches!(op, UnaryOp::Try) && !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "try operator outside function".to_string(),
                    });
                }
                self.analyze_expr(expr);
            }
            Expr::Binary { left, right, .. } => {
                self.analyze_expr(left);
                self.analyze_expr(right);
            }
            Expr::Call { callee, args } => {
                self.analyze_expr(callee);
                for a in args { self.analyze_expr(a); }
            }
            Expr::Field { object, .. } => self.analyze_expr(object),
            Expr::MethodCall { object, args, .. } => {
                self.analyze_expr(object);
                for a in args { self.analyze_expr(a); }
            }
            Expr::Index { object, index } => {
                self.analyze_expr(object);
                self.analyze_expr(index);
            }
            Expr::If { cond, then_block, else_block } => {
                self.analyze_expr(cond);
                self.push_scope();
                for s in then_block { self.analyze_stmt(s); }
                self.pop_scope();

                if let Some(eb) = else_block {
                    self.push_scope();
                    for s in eb { self.analyze_stmt(s); }
                    self.pop_scope();
                }
            }
            Expr::Command(cmd) | Expr::CaptureCommand(cmd) | Expr::AsyncCommand(cmd) => {
                for pipe in &cmd.pipelines {
                    for c in &pipe.commands {
                        for arg in &c.args {
                            self.analyze_expr(arg);
                        }
                        for r in &c.redirections {
                            match r {
                                Redirection::In(e) | Redirection::Out(e) | Redirection::Append(e) |
                                Redirection::ErrOut(e) | Redirection::ErrAppend(e) | Redirection::HereString(e) => {
                                    self.analyze_expr(e);
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
    }
}
EOF"}

