        self.errors.push(AnalysisError {
            line,
            column: col,
            message: format!("undeclared variable '{}'", name),
        });
    }

    pub fn analyze_program(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            self.analyze_stmt(stmt);
        }
    }

    pub fn analyze_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Let { name, init } => {
                if let Some(expr) = init {
                    self.analyze_expr(expr);
                }
                self.declare_var(name, 1, 0); // location approximated if needed
            }
            Stmt::Assign { target, value } => {
                self.analyze_expr(value);
                match target {
                    AssignTarget::Var(n) => self.check_var(n, 1, 0),
                    AssignTarget::Field { object, .. } => self.analyze_expr(object),
                    AssignTarget::Index { object, index } => {
                        self.analyze_expr(object);
                        self.analyze_expr(index);
                    }
                }
            }
            Stmt::If { cond, then_block, else_block } => {
                self.analyze_expr(cond);
                self.push_scope();
                for s in then_block { self.analyze_stmt(s); }
                self.pop_scope();

                if let Some(eb) = else_block {
                    self.push_scope();
                    for s in eb { self.analyze_stmt(s); }
                    self.pop_scope();
                }
            }
            Stmt::While { cond, body } => {
                self.analyze_expr(cond);
                let old_loop = self.in_loop;
                self.in_loop = true;
                self.push_scope();
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
                self.in_loop = old_loop;
            }
            Stmt::For { var, iter, body } => {
                self.analyze_expr(iter);
                let old_loop = self.in_loop;
                self.in_loop = true;
                self.push_scope();
                self.declare_var(var, 1, 0);
                for s in body { self.analyze_stmt(s); }
                self.pop_scope();
                self.in_loop = old_loop;
            }
            Stmt::Break => {
                if !self.in_loop {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "break statement outside loop".to_string(),
                    });
                }
            }
            Stmt::Return(opt_expr) => {
                if !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "return statement outside function".to_string(),
                    });
                }
                if let Some(expr) = opt_expr {
                    self.analyze_expr(expr);
                }
            }
            Stmt::Expr(expr) => self.analyze_expr(expr),
        }
    }

    pub fn analyze_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::Literal(_) => {}
            Expr::Var(name) => self.check_var(name, 1, 0),
            Expr::SelfKw => {
                if !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "self keyword outside function".to_string(),
                    });
                }
            }
            Expr::Array(items) => {
                for item in items { self.analyze_expr(item); }
            }
            Expr::Dict(entries) => {
                for (_, v) in entries { self.analyze_expr(v); }
            }
            Expr::Func { params, body } => {
                let old_func = self.in_func;
                let old_loop = self.in_loop;
                self.in_func = true;
                self.in_loop = false;

                self.push_scope();
                for p in params {
                    self.declare_var(p, 1, 0);
                }
                for s in body {
                    self.analyze_stmt(s);
                }
                self.pop_scope();

                self.in_func = old_func;
                self.in_loop = old_loop;
            }
            Expr::Unary { op, expr } => {
                if matches!(op, UnaryOp::Try) && !self.in_func {
                    self.errors.push(AnalysisError {
                        line: 1, column: 0,
                        message: "try operator outside function".to_string(),
                    });
                }
                self.analyze_expr(expr);
            }
            Expr::Binary { left, right, .. } => {
                self.analyze_expr(left);
                self.analyze_expr(right);
            }
            Expr::Call { callee, args } => {
                self.analyze_expr(callee);
                for a in args { self.analyze_expr(a); }
            }
            Expr::Field { object, .. } => self.analyze_expr(object),
            Expr::MethodCall { object, args, .. } => {
                self.analyze_expr(object);
                for a in args { self.analyze_expr(a); }
            }
            Expr::Index { object, index } => {
                self.analyze_expr(object);
                self.analyze_expr(index);
            }
            Expr::If { cond, then_block, else_block } => {
                self.analyze_expr(cond);
                self.push_scope();
                for s in then_block { self.analyze_stmt(s); }
                self.pop_scope();

                if let Some(eb) = else_block {
                    self.push_scope();
                    for s in eb { self.analyze_stmt(s); }
                    self.pop_scope();
                }
            }
            Expr::Command(cmd) | Expr::CaptureCommand(cmd) | Expr::AsyncCommand(cmd) => {
                for pipe in &cmd.pipelines {
                    for c in &pipe.commands {
                        for arg in &c.args {
                            self.analyze_expr(arg);
                        }
                        for r in &c.redirections {
                            match r {
                                Redirection::In(e) | Redirection::Out(e) | Redirection::Append(e) |
                                Redirection::ErrOut(e) | Redirection::ErrAppend(e) | Redirection::HereString(e) => {
                                    self.analyze_expr(e);
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
    }
}
EOF"}

{"command":"cat << 'EOF' > src/value.rs
use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;
use crate::ast::Stmt;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Char(char),
    String(String),
    Array(Rc<RefCell<Vec<Value>>>),
    Dict(Rc<RefCell<HashMap<String, Value>>>),
    Function {
        params: Vec<String>,
        body: Vec<Stmt>,
        env: HashMap<String, Value>,
        bound_self: Option<Box<Value>>,
        loc_str: String,
    },
    BuiltinFunc {
        name: String,
        func: fn(args: Vec<Value>, evaluator: &mut crate::eval::Evaluator) -> Result<Value, Value>,
    },
    Error {
        message: String,
        detail: Box<Value>,
    },
    RangeIter {
        current: i64,
        end: i64,
        step: i64,
    },
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Char(_) => "char",
            Value::String(_) => "string",
            Value::Array(_) => "array",
            Value::Dict(_) => "dict",
            Value::Function { .. } | Value::BuiltinFunc { .. } | Value::RangeIter { .. } => "function",
            Value::Error { .. } => "error",
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Nil => false,
            Value::Bool(b) => *b,
            _ => true,
        }
    }

    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Int(i) => i.to_string(),
            Value::Float(f) => {
                if f.fract() == 0.0 && !f.is_infinite() {
                    format!("{:.1}", f)
                } else {
                    f.to_string()
                }
            }
            Value::Char(c) => c.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(arr) => {
                let items: Vec<String> = arr.borrow().iter().map(|v| match v {
                    Value::String(s) => format!("\"{}\"", s),
                    _ => v.to_display_string(),
                }).collect();
                if items.is_empty() {
                    "[ ]".to_string()
                } else {
                    format!("[ {} ]", items.join(", "))
                }
            }
            Value::Dict(d) => {
                let map = d.borrow();
                let mut entries: Vec<String> = map.iter().map(|(k, v)| {
                    let v_str = match v {
                        Value::String(s) => format!("\"{}\"", s),
                        _ => v.to_display_string(),
                    };
                    format!("\"{}\": {}", k, v_str)
                }).collect();
                entries.sort();
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
                    format!("@[ {} ]", entries.join(", "))
                }
            }
            Value::Function { loc_str, .. } => format!("function<{}>", loc_str),
            Value::BuiltinFunc { name, .. } => format!("std.{}", name),
            Value::RangeIter { .. } => "std.range<impl>".to_string(),
            Value::Error { message, detail } => {
                format!("error: \"{}\" ({})", message, detail.to_display_string())
            }
        }
    }
}

impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Int(a), Value::Float(b)) => (*a as f64) == *b,
            (Value::Float(a), Value::Int(b)) => *a == (*b as f64),
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::String(a), Value::String(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => *a.borrow() == *b.borrow(),
            (Value::Dict(a), Value::Dict(b)) => *a.borrow() == *b.borrow(),
            (Value::Error { message: m1, detail: d1 }, Value::Error { message: m2, detail: d2 }) => {
                m1 == m2 && d1 == d2
            }
            _ => false,
        }
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_display_string())
    }
}
EOF"}

