{"command":"cat << 'EOF' > src/stdlib.rs
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;
use crate::value::Value;
use crate::eval::Evaluator;

pub fn make_std_lib(args: Vec<String>) -> HashMap<String, Value> {
    let mut std_map = HashMap::new();

    std_map.insert("print".to_string(), Value::BuiltinFunc {
        name: "print".to_string(),
        func: |args, _| {
            let s: Vec<String> = args.iter().map(|v| v.to_display_string()).collect();
            print!("{}", s.join("\t"));
            Ok(Value::Nil)
        },
    });

    std_map.insert("println".to_string(), Value::BuiltinFunc {
        name: "println".to_string(),
        func: |args, _| {
            let s: Vec<String> = args.iter().map(|v| v.to_display_string()).collect();
            println!("{}", s.join("\t"));
            Ok(Value::Nil)
        },
    });

    std_map.insert("to_string".to_string(), Value::BuiltinFunc {
        name: "to_string".to_string(),
        func: |args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            Ok(Value::String(args[0].to_display_string()))
        },
    });

    std_map.insert("type".to_string(), Value::BuiltinFunc {
        name: "type".to_string(),
        func: |args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            Ok(Value::String(args[0].type_name().to_string()))
        },
    });

    std_map.insert("len".to_string(), Value::BuiltinFunc {
        name: "len".to_string(),
        func: |args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            match &args[0] {
                Value::String(s) => Ok(Value::Int(s.len() as i64)),
                Value::Array(arr) => Ok(Value::Int(arr.borrow().len() as i64)),
                Value::Dict(d) => Ok(Value::Int(d.borrow().len() as i64)),
                other => Err(Value::Error {
                    message: format!("value ({}) has unexpected type, expected string, array or dict", other.to_display_string()),
                    detail: Box::new(other.clone()),
                }),
            }
        },
    });

    std_map.insert("is_empty".to_string(), Value::BuiltinFunc {
        name: "is_empty".to_string(),
        func: |args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            match &args[0] {
                Value::String(s) => Ok(Value::Bool(s.is_empty())),
                Value::Array(arr) => Ok(Value::Bool(arr.borrow().is_empty())),
                Value::Dict(d) => Ok(Value::Bool(d.borrow().is_empty())),
                other => Err(Value::Error {
                    message: format!("value ({}) has unexpected type, expected string, array or dict", other.to_display_string()),
                    detail: Box::new(other.clone()),
                }),
            }
        },
    });

    std_map.insert("push".to_string(), Value::BuiltinFunc {
        name: "push".to_string(),
        func: |args, _| {
            if args.len() != 2 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            if let Value::Array(arr) = &args[0] {
                arr.borrow_mut().push(args[1].clone());
                Ok(args[0].clone())
            } else {
                Err(Value::Error {
                    message: format!("value ({}) has unexpected type, expected array", args[0].to_display_string()),
                    detail: Box::new(args[0].clone()),
                })
            }
        },
    });

    std_map.insert("pop".to_string(), Value::BuiltinFunc {
        name: "pop".to_string(),
        func: |args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            if let Value::Array(arr) = &args[0] {
                let mut b = arr.borrow_mut();
                if let Some(val) = b.pop() {
                    Ok(val)
                } else {
                    Err(Value::Error {
                        message: "collection is empty".to_string(),
                        detail: Box::new(Value::Nil),
                    })
                }
            } else {
                Err(Value::Error {
                    message: format!("value ({}) has unexpected type, expected array", args[0].to_display_string()),
                    detail: Box::new(args[0].clone()),
                })
            }
        },
    });

    std_map.insert("range".to_string(), Value::BuiltinFunc {
        name: "range".to_string(),
