use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;
use crate::ast::*;
use crate::value::Value;
use crate::stdlib::make_std_lib;

#[derive(Clone)]
pub struct Env {
    pub vars: HashMap<String, Value>,
}

impl Env {
    pub fn new() -> Self {
        Self { vars: HashMap::new() }
    }
}

pub struct Evaluator {
    pub filename: String,
    pub env_stack: Vec<Env>,
    pub current_self: Option<Value>,
}

impl Evaluator {
    pub fn new(filename: String, args: Vec<String>) -> Self {
        let mut global_env = Env::new();
        let std_dict = Value::Dict(Rc::new(RefCell::new(make_std_lib(args))));
        global_env.vars.insert("std".to_string(), std_dict);

        Self {
            filename,
            env_stack: vec![global_env],
            current_self: None,
        }
    }

    fn push_env(&mut self) {
        self.env_stack.push(Env::new());
    }

    fn pop_env(&mut self) {
        self.env_stack.pop();
    }

    pub fn get_var(&self, name: &str) -> Option<Value> {
        for env in self.env_stack.iter().rev() {
            if let Some(val) = env.vars.get(name) {
                return Some(val.clone());
            }
        }
        None
    }

    pub fn set_var(&mut self, name: &str, val: Value) {
        for env in self.env_stack.iter_mut().rev() {
            if env.vars.contains_key(name) {
                env.vars.insert(name.to_string(), val);
                return;
            }
        }
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn declare_var(&mut self, name: &str, val: Value) {
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn eval_program(&mut self, stmts: &[Stmt]) -> Result<Value, Value> {
        let mut last_val = Value::Nil;
        for stmt in stmts {
            last_val = self.eval_stmt(stmt)?;
        }
        Ok(last_val)
    }

    pub fn eval_stmt(&mut self, stmt: &Stmt) -> Result<Value, Value> {
        match stmt {
            Stmt::Let { name, init } => {
                let val = match init {
                    Some(expr) => self.eval_expr(expr)?,
                    None => Value::Nil,
                };
                self.declare_var(name, val);
                Ok(Value::Nil)
            }
            Stmt::Assign { target, value } => {
                let val = self.eval_expr(value)?;
                match target {
                    AssignTarget::Var(name) => {
                        self.set_var(name, val);
                    }
                    AssignTarget::Field { object, field } => {
                        let obj_val = self.eval_expr(object)?;
                        if let Value::Dict(d) = obj_val {
                            d.borrow_mut().insert(field.clone(), val);
                        } else {
                            return Err(Value::Error {
                                message: format!("value ({}) has unexpected type, expected dict", obj_val.to_display_string()),
                                detail: Box::new(obj_val),
                            });
                        }
                    }
                    AssignTarget::Index { object, index } => {
                        let obj_val = self.eval_expr(object)?;
                        let idx_val = self.eval_expr(index)?;
                        match (obj_val, idx_val) {
                            (Value::Array(arr), Value::Int(idx)) => {
                                let mut b = arr.borrow_mut();
                                if idx < 0 || (idx as usize) >= b.len() {
                                    return Err(Value::Error {
                                        message: format!("index ({}) out of bounds", idx),
                                        detail: Box::new(Value::Int(idx)),
                                    });
                                }
                                b[idx as usize] = val;
                            }
                            (Value::Dict(d), Value::String(key)) => {
                                d.borrow_mut().insert(key, val);
                            }
                            (other_obj, other_idx) => {
                                return Err(Value::Error {
                                    message: format!("value ({}) has unexpected type", other_obj.to_display_string()),
                                    detail: Box::new(other_idx),
                                });
                            }
                        }
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::If { cond, then_block, else_block } => {
                let cond_val = self.eval_expr(cond)?;
                if cond_val.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(then_block)?;
                    self.pop_env();
                    Ok(res)
                } else if let Some(eb) = else_block {
                    self.push_env();
                    let res = self.eval_program(eb)?;
                    self.pop_env();
                    Ok(res)
                } else {
                    Ok(Value::Nil)
                }
            }
            Stmt::While { cond, body } => {
                while self.eval_expr(cond)?.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(body);
                    self.pop_env();
                    if let Err(err) = res {
                        if matches!(&err, Value::String(s) if s == "break") {
                            break;
                        } else {
                            return Err(err);
                        }
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::For { var, iter, body } => {
                let iter_val = self.eval_expr(iter)?;
                match iter_val {
                    Value::RangeIter { mut current, end, step } => {
                        while (step > 0 && current < end) || (step < 0 && current > end) {
                            self.push_env();
                            self.declare_var(var, Value::Int(current));
                            let res = self.eval_program(body);
                            self.pop_env();
                            if let Err(err) = res {
                                if matches!(&err, Value::String(s) if s == "break") {
                                    break;
                                } else {
                                    return Err(err);
                                }
                            }
                            current += step;
                        }
                    }
                    Value::Function { .. } | Value::BuiltinFunc { .. } => {
                        loop {
                            let next_val = self.call_func(iter_val.clone(), vec![])?;
                            if let Value::Dict(d) = &next_val {
                                let map = d.borrow();
                                if let Some(Value::Bool(true)) = map.get("finished") {
                                    break;
                                }
                                let val = map.get("value").cloned().unwrap_or(Value::Nil);
                                self.push_env();
                                self.declare_var(var, val);
                                let res = self.eval_program(body);
                                self.pop_env();
                                if let Err(err) = res {
                                    if matches!(&err, Value::String(s) if s == "break") {
                                        break;
                                    } else {
                                        return Err(err);
                                    }
                                }
                            } else if matches!(next_val, Value::Nil) {
                                break;
                            }
                        }
                    }
                    other => {
                        return Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected function", other.to_display_string()),
                            detail: Box::new(other),
                        });
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::Break => Err(Value::String("break".to_string())),
            Stmt::Return(opt_expr) => {
                let val = match opt_expr {
                    Some(e) => self.eval_expr(e)?,
                    None => Value::Nil,
                };
                Err(Value::Error { message: "return".to_string(), detail: Box::new(val) })
            }
            Stmt::Expr(expr) => self.eval_expr(expr),
        }
    }

    pub fn eval_expr(&mut self, expr: &Expr) -> Result<Value, Value> {
        match expr {
            Expr::Literal(val) => match val {
                LiteralValue::Nil => Ok(Value::Nil),
                LiteralValue::Bool(b) => Ok(Value::Bool(*b)),
                LiteralValue::Int(i) => Ok(Value::Int(*i)),
                LiteralValue::Float(f) => Ok(Value::Float(*f)),
                LiteralValue::Char(c) => Ok(Value::Char(*c)),
                LiteralValue::String(s) => Ok(Value::String(s.clone())),
            },
            Expr::Var(name) => {
                if let Some(val) = self.get_var(name) {
                    Ok(val)
                } else {
                    Err(Value::Error {
                        message: format!("undeclared variable '{}'", name),
                        detail: Box::new(Value::Nil),
                    })
                }
            }
            Expr::SelfKw => {
                if let Some(val) = &self.current_self {
                    Ok(val.clone())
                } else {
                    Ok(Value::Nil)
                }
            }
            Expr::Array(items) => {
                let mut evaluated = Vec::new();
                for item in items {
                    evaluated.push(self.eval_expr(item)?);
                }
                Ok(Value::Array(Rc::new(RefCell::new(evaluated))))
            }
            Expr::Dict(entries) => {
                let mut map = HashMap::new();
                for (k, v) in entries {
                    map.insert(k.clone(), self.eval_expr(v)?);
                }
                Ok(Value::Dict(Rc::new(RefCell::new(map))))
            }
            Expr::Func { params, body } => {
                let mut env = HashMap::new();
                if let Some(top) = self.env_stack.last() {
                    env = top.vars.clone();
                }
                Ok(Value::Function {
                    params: params.clone(),
                    body: body.clone(),
                    env,
                    bound_self: None,
                    loc_str: format!("{} (line 1, column 0)", self.filename),
                })
            }
            Expr::Unary { op, expr } => {
                let val = self.eval_expr(expr)?;
                match op {
                    UnaryOp::Neg => match val {
                        Value::Int(i) => Ok(Value::Int(-i)),
                        Value::Float(f) => Ok(Value::Float(-f)),
                        other => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int or float", other.to_display_string()),
                            detail: Box::new(other),
                        }),
                    },
                    UnaryOp::Not => Ok(Value::Bool(!val.is_truthy())),
                    UnaryOp::Try => match val {
                        Value::Error { .. } => Err(Value::Error { message: "return".to_string(), detail: Box::new(val) }),
                        other => Ok(other),
                    },
                }
            }
            Expr::Binary { op, left, right } => {
                let l_val = self.eval_expr(left)?;
                let r_val = self.eval_expr(right)?;
                match op {
                    BinaryOp::Add => match (l_val, r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a + b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
                        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(a as f64 + b)),
                        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a + b as f64)),
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Sub => match (l_val, r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a - b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
                        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(a as f64 - b)),
                        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a - b as f64)),
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Mul => match (l_val, r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a * b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
                        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(a as f64 * b)),
                        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a * b as f64)),
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Div => match (l_val, r_val) {
                        (Value::Int(a), Value::Int(b)) => {
                            if b == 0 {
                                Err(Value::Error { message: "division by zero".to_string(), detail: Box::new(Value::Nil) })
                            } else {
                                Ok(Value::Int(a / b))
                            }
                        }
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a / b)),
                        (Value::Int(a), Value::Float(b)) => Ok(Value::Float(a as f64 / b)),
                        (Value::Float(a), Value::Int(b)) => Ok(Value::Float(a / b as f64)),
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Mod => match (l_val, r_val) {
                        (Value::Int(a), Value::Int(b)) => {
                            if b == 0 {
                                Err(Value::Error { message: "division by zero".to_string(), detail: Box::new(Value::Nil) })
                            } else {
                                Ok(Value::Int(a % b))
                            }
                        }
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected int", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Concat => match (l_val, r_val) {
                        (Value::String(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::String(a), Value::Char(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::Char(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::Char(a), Value::Char(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (other_l, other_r) => Err(Value::Error {
                            message: format!("value ({}) has unexpected type, expected string", other_r.to_display_string()),
                            detail: Box::new(other_r),
                        }),
                    },
                    BinaryOp::Eq => Ok(Value::Bool(l_val == r_val)),
                    BinaryOp::NotEq => Ok(Value::Bool(l_val != r_val)),
                    BinaryOp::Lt => self.eval_cmp(l_val, r_val, |a, b| a < b),
                    BinaryOp::LtEq => self.eval_cmp(l_val, r_val, |a, b| a <= b),
                    BinaryOp::Gt => self.eval_cmp(l_val, r_val, |a, b| a > b),
                    BinaryOp::GtEq => self.eval_cmp(l_val, r_val, |a, b| a >= b),
                    BinaryOp::And => {
                        if !l_val.is_truthy() {
                            Ok(l_val)
                        } else {
                            Ok(r_val)
                        }
                    }
                    BinaryOp::Or => {
                        if l_val.is_truthy() {
                            Ok(l_val)
                        } else {
                            Ok(r_val)
                        }
                    }
                }
            }
            Expr::Call { callee, args } => {
                let callee_val = self.eval_expr(callee)?;
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a)?);
                }
                self.call_func(callee_val, arg_vals)
            }
            Expr::Field { object, field } => {
                let obj_val = self.eval_expr(object)?;
                match obj_val {
                    Value::Dict(d) => {
                        let map = d.borrow();
                        if let Some(v) = map.get(field) {
                            Ok(v.clone())
                        } else {
                            Err(Value::Error {
                                message: format!("index (\"{}\") out of bounds", field),
                                detail: Box::new(Value::String(field.clone())),
                            })
                        }
                    }
                    other => Err(Value::Error {
                        message: format!("value ({}) has unexpected type, expected string, array, dict or error", other.to_display_string()),
                        detail: Box::new(other),
                    }),
                }
            }
            Expr::MethodCall { object, method, args } => {
                let obj_val = self.eval_expr(object)?;
