                    Value::Dict(d) => {
                        let map = d.borrow();
                        if let Some(v) = map.get(method) {
                            v.clone()
                        } else {
                            return Err(Value::Error {
                                message: format!("index (\"{}\") out of bounds", method),
                                detail: Box::new(Value::String(method.clone())),
                            });
                        }
                    }
                    other => return Err(Value::Error {
                        message: format!("value ({}) has unexpected type, expected dict", other.to_display_string()),
                        detail: Box::new(other),
                    }),
                };
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a)?);
                }

                let old_self = self.current_self.clone();
                self.current_self = Some(obj_val);
                let res = self.call_func(func_val, arg_vals);
                self.current_self = old_self;
                res
            }
            Expr::Index { object, index } => {
                let obj_val = self.eval_expr(object)?;
                let idx_val = self.eval_expr(index)?;
                match (obj_val, idx_val) {
                    (Value::Array(arr), Value::Int(i)) => {
                        let b = arr.borrow();
                        if i < 0 || (i as usize) >= b.len() {
                            Err(Value::Error {
                                message: format!("index ({}) out of bounds", i),
                                detail: Box::new(Value::Int(i)),
                            })
                        } else {
                            Ok(b[i as usize].clone())
                        }
                    }
                    (Value::Dict(d), Value::String(s)) => {
                        let b = d.borrow();
                        if let Some(val) = b.get(&s) {
                            Ok(val.clone())
                        } else {
                            Err(Value::Error {
                                message: format!("index (\"{}\") out of bounds", s),
                                detail: Box::new(Value::String(s)),
                            })
                        }
                    }
                    (other_obj, other_idx) => Err(Value::Error {
                        message: format!("value ({}) has unexpected type, expected string, array, dict or error", other_obj.to_display_string()),
                        detail: Box::new(other_idx),
                    }),
                }
            }
            Expr::If { cond, then_block, else_block } => {
                let cond_val = self.eval_expr(cond)?;
                if cond_val.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(then_block)?;
                    self.pop_env();
                    Ok(res)
                } else if let Some(eb) = else_block {
                    self.push_env();
                    let res = self.eval_program(eb)?;
                    self.pop_env();
                    Ok(res)
                } else {
                    Ok(Value::Nil)
                }
            }
            Expr::Command(cmd) => self.eval_command_block(cmd, false, false),
            Expr::CaptureCommand(cmd) => self.eval_command_block(cmd, true, false),
            Expr::AsyncCommand(cmd) => self.eval_command_block(cmd, false, true),
        }
    }

    fn eval_cmp<F>(&self, l: Value, r: Value, op: F) -> Result<Value, Value>
    where F: Fn(f64, f64) -> bool {
        let (num_l, num_r) = match (l, r) {
            (Value::Int(a), Value::Int(b)) => (a as f64, b as f64),
            (Value::Float(a), Value::Float(b)) => (a, b),
            (Value::Int(a), Value::Float(b)) => (a as f64, b),
            (Value::Float(a), Value::Int(b)) => (a, b as f64),
            (other_l, other_r) => return Err(Value::Error {
                message: format!("value ({}) has unexpected type, expected int, float, byte or string", other_l.to_display_string()),
                detail: Box::new(other_l),
            }),
        };
        Ok(Value::Bool(op(num_l, num_r)))
    }

    pub fn call_func(&mut self, callee: Value, args: Vec<Value>) -> Result<Value, Value> {
        match callee {
            Value::Function { params, body, env, bound_self, .. } => {
                if args.len() != params.len() {
                    return Err(Value::Error {
                        message: format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), params.len()),
                        detail: Box::new(Value::Nil),
                    });
                }
                let mut new_env = Env::new();
                new_env.vars.extend(env);
                for (param, arg) in params.iter().zip(args.iter()) {
                    new_env.vars.insert(param.clone(), arg.clone());
                }

                let old_self = self.current_self.clone();
                if let Some(bs) = bound_self {
                    self.current_self = Some(*bs);
                }

                self.env_stack.push(new_env);
                let res = self.eval_program(&body);
                self.env_stack.pop();

                self.current_self = old_self;

                match res {
                    Ok(val) => Ok(val),
                    Err(err) => match err {
                        Value::Error { message, detail } if message == "return" => Ok(*detail),
                        other => Err(other),
                    },
                }
            }
            Value::BuiltinFunc { func, .. } => {
                func(args, self)
            }
            other => Err(Value::Error {
                message: format!("attempt to call ({}), which is not a function", other.to_display_string()),
                detail: Box::new(other),
            }),
        }
    }

    fn eval_command_block(&mut self, cmd: &CommandBlock, capture: bool, async_block: bool) -> Result<Value, Value> {
        // Execute command pipelines using std::process::Command
        let mut last_status = 0;
        let mut captured_stdout = String::new();
        let mut captured_stderr = String::new();

        for pipe in &cmd.pipelines {
            for c in &pipe.commands {
                let mut cmd_args = Vec::new();
                for arg_expr in &c.args {
                    let v = self.eval_expr(arg_expr)?;
                    cmd_args.push(v.to_display_string());
                }

                if cmd_args.is_empty() {
                    continue;
                }

                let program = &cmd_args[0];
                let mut process_cmd = std::process::Command::new(program);
                if cmd_args.len() > 1 {
                    process_cmd.args(&cmd_args[1..]);
                }

                if capture {
                    let output = process_cmd.output().map_err(|e| Value::Error {
                        message: e.to_string(),
                        detail: Box::new(Value::Nil),
                    })?;
                    captured_stdout.push_str(&String::from_utf8_lossy(&output.stdout));
                    captured_stderr.push_str(&String::from_utf8_lossy(&output.stderr));
                    if !output.status.success() {
                        last_status = output.status.code().unwrap_or(1);
                    }
                } else {
                    let status = process_cmd.status().map_err(|e| Value::Error {
                        message: e.to_string(),
                        detail: Box::new(Value::Nil),
                    })?;
                    if !status.success() {
                        last_status = status.code().unwrap_or(1);
                    }
                }
            }
        }

        if capture {
            if last_status != 0 {
                let mut err_map = HashMap::new();
                err_map.insert("stdout".to_string(), Value::String(captured_stdout));
                err_map.insert("stderr".to_string(), Value::String(captured_stderr));
                let mut status_map = HashMap::new();
                status_map.insert("status".to_string(), Value::Int(last_status as i64));
                err_map.insert("error".to_string(), Value::Dict(Rc::new(RefCell::new(status_map))));
                Ok(Value::Error {
                    message: "command returned non-zero".to_string(),
                    detail: Box::new(Value::Dict(Rc::new(RefCell::new(err_map)))),
                })
            } else {
                let mut map = HashMap::new();
                map.insert("stdout".to_string(), Value::String(captured_stdout));
                map.insert("stderr".to_string(), Value::String(captured_stderr));
                Ok(Value::Dict(Rc::new(RefCell::new(map))))
            }
        } else if last_status != 0 {
            let mut map = HashMap::new();
            map.insert("status".to_string(), Value::Int(last_status as i64));
            map.insert("pos".to_string(), Value::String(format!("{} (line 1, column 0)", self.filename)));
            Ok(Value::Error {
                message: "command returned non-zero".to_string(),
                detail: Box::new(Value::Dict(Rc::new(RefCell::new(map)))),
            })
        } else {
            Ok(Value::Nil)
        }
    }
}
