    next_reg: usize,
    var_map: HashMap<String, usize>,
}

impl ProgramIrGenerator {
    pub fn new() -> Self {
        let mut var_map = HashMap::new();
        var_map.insert("std".to_string(), 0);
        Self {
            next_reg: 1,
            var_map,
        }
    }

    fn alloc_reg_for_var(&mut self, name: &str) -> usize {
        if let Some(&r) = self.var_map.get(name) {
            r
        } else {
            let r = self.next_reg;
            self.next_reg += 1;
            self.var_map.insert(name.to_string(), r);
            r
        }
    }

    pub fn generate_program_ir(&mut self, filename: &str, stmts: &[Stmt]) -> String {
        let mut decls = Vec::new();
        let mut body_lines = Vec::new();

        // First pass: allocate registers for all let statements
        self.collect_vars(stmts);

        for r in 0..self.next_reg {
            decls.push(format!("let #{}: auto", r));
        }

        for stmt in stmts {
            body_lines.push(self.format_stmt(stmt, 0));
        }

        let mut out = format!("--------------------------------------------------\nProgram for {}\n", filename);
        for d in decls {
            out.push_str(&format!("{}\n", d));
        }
        for b in body_lines {
            out.push_str(&format!("{}\n", b));
        }
        out.push_str("--------------------------------------------------");
        out
    }

    fn collect_vars(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            match stmt {
                Stmt::Let { name, .. } => {
                    self.alloc_reg_for_var(name);
                }
                Stmt::For { var, .. } => {
                    self.alloc_reg_for_var(var);
                }
                _ => {}
            }
        }
    }

    fn format_expr(&mut self, expr: &Expr) -> String {
        match expr {
            Expr::Literal(val) => match val {
                LiteralValue::Nil => "nil".to_string(),
                LiteralValue::Bool(b) => b.to_string(),
                LiteralValue::Int(i) => i.to_string(),
                LiteralValue::Float(f) => format!("{:?}", f),
                LiteralValue::Char(c) => format!("'{}'", c),
                LiteralValue::String(s) => format!("\"{}\"", s.escape_debug()),
            },
            Expr::Var(name) => {
                let reg = self.alloc_reg_for_var(name);
                format!("#{}", reg)
            }
            Expr::SelfKw => "#self".to_string(),
            Expr::Array(items) => {
                if items.is_empty() {
                    "[]".to_string()
                } else {
                    let mut s = "[\n".to_string();
                    for (i, item) in items.iter().enumerate() {
                        s.push_str(&format!("\t{}", self.format_expr(item)));
                        if i + 1 < items.len() { s.push_str(",\n"); } else { s.push('\n'); }
                    }
                    s.push_str("]");
                    s
                }
            }
            Expr::Dict(entries) => {
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
                    let mut s = "@[\n".to_string();
                    for (i, (k, v)) in entries.iter().enumerate() {
                        s.push_str(&format!("\t{}: {}", k, self.format_expr(v)));
                        if i + 1 < entries.len() { s.push_str(",\n"); } else { s.push('\n'); }
                    }
                    s.push_str("]");
                    s
                }
            }
            Expr::Func { params, body } => {
                let mut inner_gen = ProgramIrGenerator::new();
                inner_gen.next_reg = 0;
                for p in params {
                    inner_gen.alloc_reg_for_var(p);
                }
                inner_gen.collect_vars(body);

                let mut s = format!("function({})\n", params.len());
                for r in 0..inner_gen.next_reg {
                    s.push_str(&format!("\tlet #{}: auto\n", r));
                }
                for stmt in body {
                    s.push_str(&format!("\t{}\n", inner_gen.format_stmt(stmt, 1)));
                }
                s.push_str("end");
                s
            }
            Expr::Unary { op, expr } => match op {
                UnaryOp::Neg => format!("(- {})", self.format_expr(expr)),
                UnaryOp::Not => format!("(not {})", self.format_expr(expr)),
                UnaryOp::Try => format!("({} ?)", self.format_expr(expr)),
            },
            Expr::Binary { op, left, right } => {
                let op_str = match op {
                    BinaryOp::Add => "+", BinaryOp::Sub => "-", BinaryOp::Mul => "*", BinaryOp::Div => "/", BinaryOp::Mod => "%",
                    BinaryOp::Concat => "++", BinaryOp::Eq => "==", BinaryOp::NotEq => "!=", BinaryOp::Lt => "<",
                    BinaryOp::LtEq => "<=", BinaryOp::Gt => ">", BinaryOp::GtEq => ">=", BinaryOp::And => "and", BinaryOp::Or => "or",
                };
                format!("({} {} {})", self.format_expr(left), op_str, self.format_expr(right))
            }
            Expr::Call { callee, args } => {
                let arg_strs: Vec<String> = args.iter().map(|a| self.format_expr(a)).collect();
                format!("{}({})", self.format_expr(callee), arg_strs.join(", "))
            }
            Expr::Field { object, field } => {
                format!("{}.{}", self.format_expr(object), field)
            }
            Expr::MethodCall { object, method, args } => {
                let arg_strs: Vec<String> = args.iter().map(|a| self.format_expr(a)).collect();
                format!("{}.{}({})", self.format_expr(object), method, arg_strs.join(", "))
            }
            Expr::Index { object, index } => {
                format!("{}[{}]", self.format_expr(object), self.format_expr(index))
            }
            Expr::If { cond, then_block, else_block } => {
                let mut s = format!("if {} then\n", self.format_expr(cond));
                for stmt in then_block {
                    s.push_str(&format!("\t{}\n", self.format_stmt(stmt, 1)));
                }
                if let Some(eb) = else_block {
                    s.push_str("else\n");
                    for stmt in eb {
                        s.push_str(&format!("\t{}\n", self.format_stmt(stmt, 1)));
                    }
                }
                s.push_str("end");
                s
            }
            Expr::Command(cmd) => cmd.to_ir_string(self),
            Expr::CaptureCommand(cmd) => format!("${}", cmd.to_ir_string(self)),
            Expr::AsyncCommand(cmd) => format!("&{}", cmd.to_ir_string(self)),
        }
    }

    fn format_stmt(&mut self, stmt: &Stmt, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match stmt {
            Stmt::Let { name, init } => {
                let reg = self.alloc_reg_for_var(name);
                match init {
                    Some(e) => format!("{}#{} = {}", ind, reg, self.format_expr(e)),
                    None => format!("{}#{} = nil", ind, reg),
                }
            }
            Stmt::Assign { target, value } => {
                let tgt_str = match target {
                    AssignTarget::Var(n) => format!("#{}", self.alloc_reg_for_var(n)),
                    AssignTarget::Field { object, field } => format!("{}[{}]", self.format_expr(object), field),
                    AssignTarget::Index { object, index } => format!("{}[{}]", self.format_expr(object), self.format_expr(index)),
                };
                format!("{}{} = {}", ind, tgt_str, self.format_expr(value))
            }
            Stmt::If { cond, then_block, else_block } => {
                let mut s = format!("{}if {} then\n", ind, self.format_expr(cond));
                for stmt in then_block {
                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                if let Some(eb) = else_block {
                    s.push_str(&format!("{}else\n", ind));
                    for stmt in eb {
                        s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                    }
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::While { cond, body } => {
