                for stmt in body {
                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::Break => format!("{}break", ind),
            Stmt::Return(opt_expr) => match opt_expr {
                Some(e) => format!("{}return {}", ind, self.format_expr(e)),
                None => format!("{}return nil", ind),
            },
