                        Redirection::ErrAppend(e) => cmd_str.push(format!("2>>{}", gen.format_expr(e))),
                        Redirection::ErrToOut => cmd_str.push("2>1".to_string()),
                        Redirection::OutToErr => cmd_str.push("1>2".to_string()),
                        Redirection::HereString(e) => cmd_str.push(format!("<<{}", gen.format_expr(e))),
                    }
                }
                if cmd.try_op {
                    cmd_str.push("?".to_string());
                }
                pipe_cmds.push(cmd_str.join(" "));
            }
            s.push_str(&pipe_cmds.join(" | "));
            if i + 1 < self.pipelines.len() {
                s.push_str(";\n");
            } else {
                s.push('\n');
            }
        }
        s.push_str("}");
        s
    }
}
EOF"}

