{"command":"cat << 'EOF' > src/value.rs
use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;
use crate::ast::Stmt;

#[derive(Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Char(char),
    String(String),
    Array(Rc<RefCell<Vec<Value>>>),
    Dict(Rc<RefCell<HashMap<String, Value>>>),
    Function {
        params: Vec<String>,
        body: Vec<Stmt>,
        env: HashMap<String, Value>,
        bound_self: Option<Box<Value>>,
        loc_str: String,
    },
    BuiltinFunc {
        name: String,
        func: Rc<dyn Fn(Vec<Value>, &mut crate::eval::Evaluator) -> Result<Value, Value>>,
    },
    Error {
        message: String,
        detail: Box<Value>,
    },
    RangeIter {
        current: i64,
        end: i64,
        step: i64,
    },
}

impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Char(_) => "char",
            Value::String(_) => "string",
            Value::Array(_) => "array",
            Value::Dict(_) => "dict",
            Value::Function { .. } | Value::BuiltinFunc { .. } | Value::RangeIter { .. } => "function",
            Value::Error { .. } => "error",
        }
    }

    pub fn is_truthy(&self) -> bool {
        match self {
            Value::Nil => false,
            Value::Bool(b) => *b,
            _ => true,
        }
    }

    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Int(i) => i.to_string(),
            Value::Float(f) => {
                if f.fract() == 0.0 && !f.is_infinite() {
                    format!("{:.1}", f)
                } else {
                    f.to_string()
                }
            }
            Value::Char(c) => c.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(arr) => {
                let items: Vec<String> = arr.borrow().iter().map(|v| match v {
                    Value::String(s) => format!("\"{}\"", s),
                    _ => v.to_display_string(),
                }).collect();
                if items.is_empty() {
                    "[ ]".to_string()
                } else {
                    format!("[ {} ]", items.join(", "))
                }
            }
            Value::Dict(d) => {
                let map = d.borrow();
                let mut entries: Vec<String> = map.iter().map(|(k, v)| {
                    let v_str = match v {
                        Value::String(s) => format!("\"{}\"", s),
                        _ => v.to_display_string(),
                    };
                    format!("\"{}\": {}", k, v_str)
                }).collect();
                entries.sort();
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
                    format!("@[ {} ]", entries.join(", "))
                }
            }
            Value::Function { loc_str, .. } => format!("function<{}>", loc_str),
            Value::BuiltinFunc { name, .. } => format!("std.{}", name),
            Value::RangeIter { .. } => "std.range<impl>".to_string(),
            Value::Error { message, detail } => {
                format!("error: \"{}\" ({})", message, detail.to_display_string())
            }
        }
    }
}

impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Int(a), Value::Float(b)) => (*a as f64) == *b,
            (Value::Float(a), Value::Int(b)) => *a == (*b as f64),
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::String(a), Value::String(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => *a.borrow() == *b.borrow(),
            (Value::Dict(a), Value::Dict(b)) => *a.borrow() == *b.borrow(),
            (Value::Error { message: m1, detail: d1 }, Value::Error { message: m2, detail: d2 }) => {
                m1 == m2 && d1 == d2
            }
            _ => false,
        }
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_display_string())
    }
}
EOF"}

