            if args.len() != 3 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            let start = match &args[0] { Value::Int(i) => *i, _ => return Err(Value::Error { message: "expected int".to_string(), detail: Box::new(args[0].clone()) }) };
            let end = match &args[1] { Value::Int(i) => *i, _ => return Err(Value::Error { message: "expected int".to_string(), detail: Box::new(args[1].clone()) }) };
            let step = match &args[2] { Value::Int(i) => *i, _ => return Err(Value::Error { message: "expected int".to_string(), detail: Box::new(args[2].clone()) }) };
            Ok(Value::RangeIter { current: start, end, step })
        }),
    });

    let script_args = args.clone();
    std_map.insert("args".to_string(), Value::BuiltinFunc {
        name: "args".to_string(),
        func: Rc::new(move |_, _| {
            let items: Vec<Value> = script_args.iter().map(|a| Value::String(a.clone())).collect();
            Ok(Value::Array(Rc::new(RefCell::new(items))))
        }),
    });

    std_map.insert("assert".to_string(), Value::BuiltinFunc {
        name: "assert".to_string(),
        func: Rc::new(|args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            if !args[0].is_truthy() {
                Err(Value::Error { message: "assertion failed".to_string(), detail: Box::new(args[0].clone()) })
            } else {
                Ok(Value::Nil)
            }
        }),
    });

    std_map.insert("panic".to_string(), Value::BuiltinFunc {
        name: "panic".to_string(),
        func: Rc::new(|args, _| {
            let msg = if !args.is_empty() { args[0].to_display_string() } else { "panic".to_string() };
            Err(Value::Error { message: format!("std.panic(\"{}\")", msg), detail: Box::new(Value::Nil) })
        }),
    });

    std_map.insert("error".to_string(), Value::BuiltinFunc {
        name: "error".to_string(),
        func: Rc::new(|args, _| {
            if args.len() != 2 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            Ok(Value::Error {
                message: args[0].to_display_string(),
                detail: Box::new(args[1].clone()),
            })
        }),
    });

    std_map.insert("has_error".to_string(), Value::BuiltinFunc {
        name: "has_error".to_string(),
        func: Rc::new(|args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            Ok(Value::Bool(matches!(args[0], Value::Error { .. })))
        }),
    });

    std_map.insert("exit".to_string(), Value::BuiltinFunc {
        name: "exit".to_string(),
        func: Rc::new(|args, _| {
            if args.len() != 1 {
                return Err(Value::Error { message: "incorrect amount of function parameters".to_string(), detail: Box::new(Value::Nil) });
            }
            let code = match &args[0] {
                Value::Int(i) => *i as i32,
                other => return Err(Value::Error {
                    message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                    detail: Box::new(other.clone()),
                }),
            };
            std::process::exit(code);
        }),
    });

    std_map
}
EOF"}

