impl CommandBlock {
    pub fn to_ast_string(&self, indent: usize, prefix: &str) -> String {
        let ind = "\t".repeat(indent);
        let mut s = format!("{}{{\n", prefix);
        for (i, pipe) in self.pipelines.iter().enumerate() {
            s.push_str(&format!("{}\t", ind));
            let mut pipe_cmds = Vec::new();
            for cmd in &pipe.commands {
