        }
        for b in body_lines {
            out.push_str(&format!("{}\n", b));
        }
        out.push_str("--------------------------------------------------");
        out
    }

    fn collect_vars(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            match stmt {
                Stmt::Let { name, .. } => {
                    self.alloc_reg_for_var(name);
                }
                Stmt::For { var, .. } => {
                    self.alloc_reg_for_var(var);
