            Expr::CaptureCommand(cmd) => format!("${}", cmd.to_ir_string(self)),
            Expr::AsyncCommand(cmd) => format!("&{}", cmd.to_ir_string(self)),
        }
    }

    fn format_stmt(&mut self, stmt: &Stmt, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match stmt {
            Stmt::Let { name, init } => {
                let reg = self.alloc_reg_for_var(name);
