{"command":"cat << 'EOF' > src/lexer.rs
use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    Let,
    If,
    Then,
    Else,
    End,
    While,
    Do,
    For,
    In,
    Break,
    Return,
    Function,
    And,
    Or,
    Not,
    True,
    False,
    Nil,
    SelfKw,

    Ident(String),
    Int(i64),
    Float(f64),
    Char(char),
    StringLit(String),

    LParen,
    RParen,
    LBracket,
    RBracket,
    DictOpen,  // @[
    LBrace,    // {
    TryBrace,  // ${
    AsyncBrace,// &{
    RBrace,    // }
    Comma,
    Colon,
    Semicolon,
    Dot,
    Assign,
    Eq,
    NotEq,
    Lt,
    LtEq,
    Gt,
    GtEq,
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Concat,    // ++
    Question,  // ?

    Pipe,
    RedirectIn,
    RedirectOut,
    RedirectAppend,
    RedirectErr,
    RedirectErrAppend,
    RedirectErrToOut,
    RedirectOutToErr,
    HereString,

    CmdArg(String),
    CmdInterp(String),
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub text: String,
    pub line: usize,
    pub column: usize,
}

#[derive(Debug, Clone)]
pub struct LexError {
    pub line: usize,
    pub column: usize,
    pub message: String,
}

pub struct Lexer {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    column: usize,
    pub errors: Vec<LexError>,
    in_cmd_block: usize,
}

impl Lexer {
    pub fn new(source: &str) -> Self {
        Self {
            chars: source.chars().collect(),
            pos: 0,
            line: 1,
            column: 0,
            errors: Vec::new(),
            in_cmd_block: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_nth(&self, n: usize) -> Option<char> {
        self.chars.get(self.pos + n).copied()
    }

    fn advance(&mut self) -> Option<char> {
        if let Some(ch) = self.peek() {
            self.pos += 1;
            if ch == '\n' {
                self.line += 1;
                self.column = 0;
            } else {
                self.column += 1;
            }
            Some(ch)
        } else {
            None
        }
    }

    pub fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        while self.pos < self.chars.len() {
            self.skip_whitespace_and_comments();
            if self.pos >= self.chars.len() {
                break;
            }

            let start_line = self.line;
            let start_col = self.column;

            if let Some(tok) = self.next_token(start_line, start_col) {
                tokens.push(tok);
            }
        }
        tokens
    }

    fn skip_whitespace_and_comments(&mut self) {
        while let Some(ch) = self.peek() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '#' {
                while let Some(c) = self.peek() {
                    if c == '\n' {
                        break;
                    }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn next_token(&mut self, line: usize, col: usize) -> Option<Token> {
        let ch = self.peek()?;

        if self.in_cmd_block > 0 {
            return self.next_cmd_token(line, col);
        }

        // Keywords or Identifiers
        if ch.is_alphabetic() || ch == '_' {
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c.is_alphanumeric() || c == '_' {
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            }
            let kind = match s.as_str() {
                "let" => TokenKind::Let,
                "if" => TokenKind::If,
                "then" => TokenKind::Then,
                "else" => TokenKind::Else,
                "end" => TokenKind::End,
                "while" => TokenKind::While,
                "do" => TokenKind::Do,
                "for" => TokenKind::For,
                "in" => TokenKind::In,
                "break" => TokenKind::Break,
                "return" => TokenKind::Return,
                "function" => TokenKind::Function,
                "and" => TokenKind::And,
                "or" => TokenKind::Or,
                "not" => TokenKind::Not,
                "true" => TokenKind::True,
                "false" => TokenKind::False,
                "nil" => TokenKind::Nil,
                "self" => TokenKind::SelfKw,
                _ => TokenKind::Ident(s.clone()),
            };
            return Some(Token { kind, text: s, line, column: col });
        }

        // Numbers
        if ch.is_ascii_digit() {
            return Some(self.lex_number(line, col));
        }

        // Strings
        if ch == '"' {
            return Some(self.lex_string(line, col));
        }

        // Chars
        if ch == '\'' {
            return Some(self.lex_char(line, col));
        }

        // @[
        if ch == '@' && self.peek_nth(1) == Some('[') {
            self.advance();
            self.advance();
            return Some(Token { kind: TokenKind::DictOpen, text: "@[".to_string(), line, column: col });
        }

        // ${ or &{ or {
        if ch == '$' && self.peek_nth(1) == Some('{') {
            self.advance();
            self.advance();
            self.in_cmd_block += 1;
            return Some(Token { kind: TokenKind::TryBrace, text: "${".to_string(), line, column: col });
        }
        if ch == '&' && self.peek_nth(1) == Some('{') {
            self.advance();
            self.advance();
            self.in_cmd_block += 1;
            return Some(Token { kind: TokenKind::AsyncBrace, text: "&{".to_string(), line, column: col });
        }
        if ch == '{' {
            self.advance();
            self.in_cmd_block += 1;
            return Some(Token { kind: TokenKind::LBrace, text: "{".to_string(), line, column: col });
        }

        // Two-character operators
        if ch == '=' && self.peek_nth(1) == Some('=') {
            self.advance(); self.advance();
            return Some(Token { kind: TokenKind::Eq, text: "==".to_string(), line, column: col });
        }
        if ch == '!' && self.peek_nth(1) == Some('=') {
            self.advance(); self.advance();
            return Some(Token { kind: TokenKind::NotEq, text: "!=".to_string(), line, column: col });
        }
        if ch == '<' && self.peek_nth(1) == Some('=') {
            self.advance(); self.advance();
            return Some(Token { kind: TokenKind::LtEq, text: "<=".to_string(), line, column: col });
        }
        if ch == '>' && self.peek_nth(1) == Some('=') {
            self.advance(); self.advance();
            return Some(Token { kind: TokenKind::GtEq, text: ">=".to_string(), line, column: col });
        }
        if ch == '+' && self.peek_nth(1) == Some('+') {
            self.advance(); self.advance();
            return Some(Token { kind: TokenKind::Concat, text: "++".to_string(), line, column: col });
        }

        // Single-character punctuation & operators
        self.advance();
        let (kind, text) = match ch {
            '(' => (TokenKind::LParen, "(".to_string()),
            ')' => (TokenKind::RParen, ")".to_string()),
            '[' => (TokenKind::LBracket, "[".to_string()),
            ']' => (TokenKind::RBracket, "]".to_string()),
            ',' => (TokenKind::Comma, ",".to_string()),
            ':' => (TokenKind::Colon, ":".to_string()),
            '.' => (TokenKind::Dot, ".".to_string()),
            '=' => (TokenKind::Assign, "=".to_string()),
            '<' => (TokenKind::Lt, "<".to_string()),
            '>' => (TokenKind::Gt, ">".to_string()),
            '+' => (TokenKind::Plus, "+".to_string()),
            '-' => (TokenKind::Minus, "-".to_string()),
            '*' => (TokenKind::Star, "*".to_string()),
            '/' => (TokenKind::Slash, "/".to_string()),
            '%' => (TokenKind::Percent, "%".to_string()),
            '?' => (TokenKind::Question, "?".to_string()),
            _ => {
                self.errors.push(LexError {
                    line,
                    column: col,
                    message: format!("unexpected '{}'.", ch),
                });
                return None;
            }
        };

        Some(Token { kind, text, line, column: col })
    }

    fn lex_number(&mut self, line: usize, col: usize) -> Token {
        let mut s = String::new();
        let mut is_float = false;

        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else if c == '.' && !is_float && self.peek_nth(1).map_or(false, |next| next.is_ascii_digit()) {
                is_float = true;
                s.push(c);
                self.advance();
            } else if (c == 'e' || c == 'E') && !s.contains('e') && !s.contains('E') {
                is_float = true;
                s.push(c);
                self.advance();
                if let Some(next) = self.peek() {
                    if next == '+' || next == '-' {
                        s.push(next);
                        self.advance();
                    }
                }
            } else {
                break;
            }
        }

        if is_float {
            let val: f64 = s.parse().unwrap_or(0.0);
            if val.fract() == 0.0 && val >= (i64::MIN as f64) && val <= (i64::MAX as f64) {
                let ival = val as i64;
                Token { kind: TokenKind::Int(ival), text: ival.to_string(), line, column: col }
            } else {
                Token { kind: TokenKind::Float(val), text: s, line, column: col }
            }
        } else {
            let val: i64 = s.parse().unwrap_or(0);
            Token { kind: TokenKind::Int(val), text: val.to_string(), line, column: col }
        }
    }

    fn lex_string(&mut self, line: usize, col: usize) -> Token {
        self.advance(); // consume opening "
        let mut raw_text = String::from("\"");
        let mut val = String::new();

        while let Some(c) = self.peek() {
            if c == '"' {
                raw_text.push(c);
                self.advance();
                break;
            } else if c == '\\' {
                raw_text.push(c);
                let err_col = self.column;
                self.advance();
                if let Some(next) = self.peek() {
                    raw_text.push(next);
                    self.advance();
                    match next {
                        'n' => val.push('\n'),
                        'r' => val.push('\r'),
                        't' => val.push('\t'),
                        '0' => val.push('\0'),
                        '"' => val.push('"'),
                        '\\' => val.push('\\'),
                        other => {
                            self.errors.push(LexError {
                                line: self.line,
                                column: err_col,
                                message: format!("invalid escape sequence '\\{}'.", other),
                            });
                        }
                    }
                }
            } else {
                raw_text.push(c);
                val.push(c);
                self.advance();
            }
        }

        Token { kind: TokenKind::StringLit(val), text: raw_text, line, column: col }
    }

    fn lex_char(&mut self, line: usize, col: usize) -> Token {
        self.advance(); // consume opening '
        let mut raw_text = String::from("'");
        let mut ch_val = '\0';

        if let Some(c) = self.peek() {
            if c == '\\' {
                raw_text.push(c);
                let err_col = self.column;
                self.advance();
                if let Some(next) = self.peek() {
                    raw_text.push(next);
                    self.advance();
                    ch_val = match next {
                        'n' => '\n',
                        'r' => '\r',
                        't' => '\t',
                        '0' => '\0',
                        '\'' => '\'',
                        '\\' => '\\',
                        other => {
                            self.errors.push(LexError {
                                line: self.line,
                                column: err_col,
                                message: format!("invalid escape sequence '\\{}'.", other),
                            });
                            '\0'
                        }
                    };
                }
            } else {
                raw_text.push(c);
                ch_val = c;
                self.advance();
            }
        }

        if self.peek() == Some('\'') {
            raw_text.push('\'');
            self.advance();
        } else {
            raw_text = "'\\0'".to_string();
        }

        Token { kind: TokenKind::Char(ch_val), text: raw_text, line, column: col }
    }

    fn next_cmd_token(&mut self, line: usize, col: usize) -> Option<Token> {
        let ch = self.peek()?;

        if ch == '}' {
            self.advance();
            self.in_cmd_block -= 1;
            return Some(Token { kind: TokenKind::RBrace, text: "}".to_string(), line, column: col });
        }

        if ch == ';' {
            self.advance();
            return Some(Token { kind: TokenKind::Semicolon, text: ";".to_string(), line, column: col });
        }

        if ch == '|' {
            self.advance();
            return Some(Token { kind: TokenKind::Pipe, text: "|".to_string(), line, column: col });
        }

        if ch == '?' {
            self.advance();
            return Some(Token { kind: TokenKind::Question, text: "?".to_string(), line, column: col });
        }

        if ch == '2' && self.peek_nth(1) == Some('>') {
            if self.peek_nth(2) == Some('1') {
                self.advance(); self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectErrToOut, text: "2>1".to_string(), line, column: col });
            } else if self.peek_nth(2) == Some('>') {
                self.advance(); self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectErrAppend, text: "2>>".to_string(), line, column: col });
            } else {
                self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectErr, text: "2>".to_string(), line, column: col });
            }
        }

        if ch == '1' && self.peek_nth(1) == Some('>') {
            if self.peek_nth(2) == Some('2') {
                self.advance(); self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectOutToErr, text: "1>2".to_string(), line, column: col });
            } else if self.peek_nth(2) == Some('>') {
                self.advance(); self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectAppend, text: "1>>".to_string(), line, column: col });
            } else {
                self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectOut, text: "1>".to_string(), line, column: col });
            }
        }

        if ch == '>' {
            if self.peek_nth(1) == Some('>') {
                self.advance(); self.advance();
                return Some(Token { kind: TokenKind::RedirectAppend, text: ">>".to_string(), line, column: col });
            } else {
                self.advance();
                return Some(Token { kind: TokenKind::RedirectOut, text: ">".to_string(), line, column: col });
            }
        }

        if ch == '<' {
            if self.peek_nth(1) == Some('<') {
                self.advance(); self.advance();
                return Some(Token { kind: TokenKind::HereString, text: "<<".to_string(), line, column: col });
            } else {
                self.advance();
                return Some(Token { kind: TokenKind::RedirectIn, text: "<".to_string(), line, column: col });
            }
        }

        if ch == '$' {
            let start_col = self.column;
            self.advance();
            let mut name = String::new();
            if self.peek() == Some('{') {
                self.advance();
                while let Some(c) = self.peek() {
                    if c == '}' {
                        self.advance();
                        break;
                    } else {
                        name.push(c);
                        self.advance();
                    }
                }
            } else {
                while let Some(c) = self.peek() {
                    if c.is_alphanumeric() || c == '_' {
                        name.push(c);
                        self.advance();
                    } else {
                        break;
                    }
                }
            }
            let text = format!("${{{{{}}}}}", name);
            return Some(Token { kind: TokenKind::CmdInterp(name), text, line, column: start_col });
        }

        if ch == '"' {
            let (raw_tok, _) = self.lex_cmd_double_quote(line, col);
            return Some(raw_tok);
        }

        if ch == '\'' {
            let tok = self.lex_string_single_quote(line, col);
            return Some(tok);
        }

        let mut word = String::new();
        while let Some(c) = self.peek() {
            if c.is_whitespace() || c == ';' || c == '|' || c == '}' || c == '?' || c == '<' || c == '>' || c == '$' {
                break;
            }
            word.push(c);
            self.advance();
        }

        if !word.is_empty() {
            return Some(Token { kind: TokenKind::CmdArg(word.clone()), text: word, line, column: col });
        }

        self.advance();
        None
    }

    fn lex_cmd_double_quote(&mut self, line: usize, col: usize) -> (Token, String) {
        self.advance();
        let mut text = String::from("\"");
        let mut val = String::new();

        while let Some(c) = self.peek() {
            if c == '"' {
                text.push('"');
                self.advance();
                break;
            } else if c == '$' {
                self.advance();
                let mut var_name = String::new();
                if self.peek() == Some('{') {
                    self.advance();
                    while let Some(vc) = self.peek() {
                        if vc == '}' {
                            self.advance();
                            break;
                        }
                        var_name.push(vc);
                        self.advance();
                    }
                } else {
                    while let Some(vc) = self.peek() {
                        if vc.is_alphanumeric() || vc == '_' {
                            var_name.push(vc);
                            self.advance();
                        } else {
                            break;
                        }
                    }
                }
                text.push_str(&format!("${{{{{}}}}}", var_name));
                val.push_str(&format!("${{{{{}}}}}", var_name));
            } else if c == '\\' {
                text.push('\\');
                self.advance();
                if let Some(next) = self.peek() {
                    text.push(next);
                    val.push(next);
                    self.advance();
                }
            } else {
                text.push(c);
                val.push(c);
                self.advance();
            }
        }

        (Token { kind: TokenKind::CmdArg(text.clone()), text: text.clone(), line, column: col }, text)
    }

    fn lex_string_single_quote(&mut self, line: usize, col: usize) -> Token {
        self.advance();
        let mut text = String::from("'");
        while let Some(c) = self.peek() {
            if c == '\'' {
                text.push('\'');
                self.advance();
                break;
            } else {
                text.push(c);
                self.advance();
            }
        }
        Token { kind: TokenKind::CmdArg(text.clone()), text: text.clone(), line, column: col }
    }
}
EOF"}

