    Return(Option<Expr>, Loc),
    Expr(Expr),
}

impl Expr {
    pub fn loc(&self) -> Loc {
        match self {
            Expr::Literal(_, l) | Expr::Var(_, l) | Expr::SelfKw(l) | Expr::Array(_, l) |
            Expr::Dict(_, l) | Expr::Func { loc: l, .. } | Expr::Unary { loc: l, .. } |
            Expr::Binary { loc: l, .. } | Expr::Call { loc: l, .. } | Expr::Field { loc: l, .. } |
            Expr::MethodCall { loc: l, .. } | Expr::Index { loc: l, .. } | Expr::If { loc: l, .. } => l.clone(),
            Expr::Command(cb) | Expr::CaptureCommand(cb) | Expr::AsyncCommand(cb) => cb.loc.clone(),
        }
    }

    pub fn to_ast_string_inline(&self) -> String {
        match self {
            Expr::Array(items, _) => {
                if items.is_empty() {
                    "[]".to_string()
                } else {
                    let item_strs: Vec<String> = items.iter().map(|i| i.to_ast_string_inline()).collect();
                    format!("[ {} ]", item_strs.join(", "))
                }
            }
            Expr::Dict(entries, _) => {
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
                    let entry_strs: Vec<String> = entries.iter().map(|(k, v)| format!("{}: {}", k, v.to_ast_string_inline())).collect();
                    format!("@[ {} ]", entry_strs.join(", "))
                }
            }
            Expr::If { cond, then_block, else_block, .. } => {
                let then_str = if then_block.len() == 1 {
                    then_block[0].to_ast_string_inline()
                } else {
                    "".to_string()
                };
                let else_str = if let Some(eb) = else_block {
                    if eb.len() == 1 {
                        format!(" else {}", eb[0].to_ast_string_inline())
                    } else {
                        "".to_string()
                    }
                } else {
                    "".to_string()
                };
                format!("if {} then {}{} end", cond.to_ast_string_inline(), then_str, else_str)
            }
            Expr::Literal(val, _) => match val {
                LiteralValue::Nil => "nil".to_string(),
                LiteralValue::Bool(b) => b.to_string(),
                LiteralValue::Int(i) => i.to_string(),
                LiteralValue::Float(f) => format!("{:?}", f),
                LiteralValue::Char(c) => format!("'{}'", c),
                LiteralValue::String(s) => format!("\"{}\"", s.escape_debug()),
            },
            Expr::Var(name, _) => name.clone(),
            Expr::SelfKw(_) => "self".to_string(),
            Expr::Unary { op, expr, .. } => match op {
                UnaryOp::Neg => format!("(- {})", expr.to_ast_string_inline()),
                UnaryOp::Not => format!("(not {})", expr.to_ast_string_inline()),
                UnaryOp::Try => format!("({} ?)", expr.to_ast_string_inline()),
            },
            Expr::Binary { op, left, right, .. } => {
                let op_str = match op {
                    BinaryOp::Add => "+", BinaryOp::Sub => "-", BinaryOp::Mul => "*", BinaryOp::Div => "/", BinaryOp::Mod => "%",
                    BinaryOp::Concat => "++", BinaryOp::Eq => "==", BinaryOp::NotEq => "!=", BinaryOp::Lt => "<",
                    BinaryOp::LtEq => "<=", BinaryOp::Gt => ">", BinaryOp::GtEq => ">=", BinaryOp::And => "and", BinaryOp::Or => "or",
                };
                format!("({} {} {})", left.to_ast_string_inline(), op_str, right.to_ast_string_inline())
            }
            Expr::Call { callee, args, .. } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_ast_string_inline()).collect();
                format!("{}({})", callee.to_ast_string_inline(), arg_strs.join(", "))
            }
            Expr::Field { object, field, .. } => {
                format!("{}.{}", object.to_ast_string_inline(), field)
            }
            Expr::MethodCall { object, method, args, .. } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_ast_string_inline()).collect();
                format!("{}.{}({})", object.to_ast_string_inline(), method, arg_strs.join(", "))
            }
            Expr::Index { object, index, .. } => {
                format!("{}[{}]", object.to_ast_string_inline(), index.to_ast_string_inline())
            }
            _ => self.to_ast_string(0),
        }
    }

    pub fn to_ast_string(&self, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match self {
            Expr::Literal(val, _) => match val {
                LiteralValue::Nil => "nil".to_string(),
                LiteralValue::Bool(b) => b.to_string(),
                LiteralValue::Int(i) => i.to_string(),
                LiteralValue::Float(f) => format!("{:?}", f),
                LiteralValue::Char(c) => format!("'{}'", c),
                LiteralValue::String(s) => format!("\"{}\"", s.escape_debug()),
            },
            Expr::Var(name, _) => name.clone(),
            Expr::SelfKw(_) => "self".to_string(),
            Expr::Array(items, _) => {
                if items.is_empty() {
                    "[]".to_string()
                } else {
                    let mut s = "[\n".to_string();
                    for (i, item) in items.iter().enumerate() {
                        s.push_str(&format!("{}\t{}", ind, item.to_ast_string(indent + 1)));
                        if i + 1 < items.len() {
                            s.push_str(",\n");
                        } else {
                            s.push('\n');
                        }
                    }
                    s.push_str(&format!("{}]", ind));
                    s
                }
            }
            Expr::Dict(entries, _) => {
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
                    let mut s = "@[\n".to_string();
                    for (i, (k, v)) in entries.iter().enumerate() {
                        s.push_str(&format!("{}\t{}: {}", ind, k, v.to_ast_string(indent + 1)));
                        if i + 1 < entries.len() {
                            s.push_str(",\n");
                        } else {
                            s.push('\n');
                        }
                    }
                    s.push_str(&format!("{}]", ind));
                    s
                }
            }
            Expr::Func { params, body, .. } => {
                let p_names: Vec<String> = params.iter().map(|p| p.0.clone()).collect();
                let mut s = format!("function({})\n", p_names.join(", "));
                for stmt in body {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Expr::Unary { op, expr, .. } => match op {
                UnaryOp::Neg => format!("(- {})", expr.to_ast_string_inline()),
                UnaryOp::Not => format!("(not {})", expr.to_ast_string_inline()),
                UnaryOp::Try => format!("({} ?)", expr.to_ast_string_inline()),
            },
            Expr::Binary { op, left, right, .. } => {
                let op_str = match op {
                    BinaryOp::Add => "+", BinaryOp::Sub => "-", BinaryOp::Mul => "*", BinaryOp::Div => "/", BinaryOp::Mod => "%",
                    BinaryOp::Concat => "++", BinaryOp::Eq => "==", BinaryOp::NotEq => "!=", BinaryOp::Lt => "<",
                    BinaryOp::LtEq => "<=", BinaryOp::Gt => ">", BinaryOp::GtEq => ">=", BinaryOp::And => "and", BinaryOp::Or => "or",
                };
                format!("({} {} {})", left.to_ast_string_inline(), op_str, right.to_ast_string_inline())
            }
            Expr::Call { callee, args, .. } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_ast_string_inline()).collect();
                format!("{}({})", callee.to_ast_string_inline(), arg_strs.join(", "))
            }
            Expr::Field { object, field, .. } => {
                format!("{}.{}", object.to_ast_string_inline(), field)
            }
            Expr::MethodCall { object, method, args, .. } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_ast_string_inline()).collect();
                format!("{}.{}({})", object.to_ast_string_inline(), method, arg_strs.join(", "))
            }
            Expr::Index { object, index, .. } => {
                format!("{}[{}]", object.to_ast_string_inline(), index.to_ast_string_inline())
            }
            Expr::If { cond, then_block, else_block, .. } => {
                let mut s = format!("if {} then\n", cond.to_ast_string(indent));
                for stmt in then_block {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                if let Some(eb) = else_block {
                    s.push_str(&format!("{}else\n", ind));
                    for stmt in eb {
                        s.push_str(&stmt.to_ast_string(indent + 1));
                        s.push('\n');
                    }
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Expr::Command(cmd) => cmd.to_ast_string(indent, ""),
            Expr::CaptureCommand(cmd) => cmd.to_ast_string(indent, "$"),
            Expr::AsyncCommand(cmd) => cmd.to_ast_string(indent, "&"),
        }
    }
}

impl Stmt {
    pub fn to_ast_string_inline(&self) -> String {
        match self {
            Stmt::Expr(expr) => expr.to_ast_string_inline(),
            _ => self.to_ast_string(0),
        }
    }

    pub fn to_ast_string(&self, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match self {
            Stmt::Let { name, init, .. } => match init {
                Some(expr) => format!("{}let {} = {}", ind, name, expr.to_ast_string(indent)),
                None => format!("{}let {} = nil", ind, name),
            },
            Stmt::Assign { target, value, .. } => {
                let tgt_str = match target {
                    AssignTarget::Var(n, _) => n.clone(),
                    AssignTarget::Field { object, field, .. } => format!("{}.{}", object.to_ast_string_inline(), field),
                    AssignTarget::Index { object, index, .. } => format!("{}[{}]", object.to_ast_string_inline(), index.to_ast_string_inline()),
                };
                format!("{}{} = {}", ind, tgt_str, value.to_ast_string(indent))
            }
            Stmt::If { cond, then_block, else_block, .. } => {
                let mut s = format!("{}if {} then\n", ind, cond.to_ast_string(indent));
                for stmt in then_block {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                if let Some(eb) = else_block {
                    s.push_str(&format!("{}else\n", ind));
                    for stmt in eb {
                        s.push_str(&stmt.to_ast_string(indent + 1));
                        s.push('\n');
                    }
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::While { cond, body, .. } => {
                let mut s = format!("{}while {} do\n", ind, cond.to_ast_string(indent));
                for stmt in body {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::For { var, iter, body, .. } => {
                let mut s = format!("{}for {} in {} do\n", ind, var, iter.to_ast_string(indent));
                for stmt in body {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::Break(_) => format!("{}break", ind),
            Stmt::Return(opt_expr, _) => match opt_expr {
                Some(expr) => format!("{}return {}", ind, expr.to_ast_string(indent)),
                None => format!("{}return nil", ind),
            },
            Stmt::Expr(expr) => format!("{}{}", ind, expr.to_ast_string(indent)),
        }
    }
}

impl CommandBlock {
    pub fn to_ast_string(&self, indent: usize, prefix: &str) -> String {
        let ind = "\t".repeat(indent);
        let mut s = format!("{}{{\n", prefix);
        for (i, pipe) in self.pipelines.iter().enumerate() {
            s.push_str(&format!("{}\t", ind));
            let mut pipe_cmds = Vec::new();
            for cmd in &pipe.commands {
                let mut cmd_str = Vec::new();
                for arg in &cmd.args {
                    cmd_str.push(arg.to_ast_string(indent + 1));
                }
                for r in &cmd.redirections {
                    match r {
                        Redirection::In(e) => cmd_str.push(format!("<{}", e.to_ast_string(indent + 1))),
                        Redirection::Out(e) => cmd_str.push(format!("1>{}", e.to_ast_string(indent + 1))),
                        Redirection::Append(e) => cmd_str.push(format!("1>>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrOut(e) => cmd_str.push(format!("2>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrAppend(e) => cmd_str.push(format!("2>>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrToOut => cmd_str.push("2>1".to_string()),
                        Redirection::OutToErr => cmd_str.push("1>2".to_string()),
                        Redirection::HereString(e) => cmd_str.push(format!("<<{}", e.to_ast_string(indent + 1))),
                    }
                }
                if cmd.try_op {
                    cmd_str.push("?".to_string());
                }
                pipe_cmds.push(cmd_str.join(" "));
            }
            s.push_str(&pipe_cmds.join(" | "));
            if i + 1 < self.pipelines.len() {
                s.push_str(";\n");
            } else {
                s.push('\n');
            }
        }
        s.push_str(&format!("{}}}", ind));
        s
    }
}
EOF"}

