                        if i + 1 < items.len() {
                            s.push_str(",\n");
                        } else {
                            s.push('\n');
                        }
                    }
                    s.push_str(&format!("{}]", ind));
                    s
                }
            }
            Expr::Dict(entries, _) => {
                if entries.is_empty() {
                    "@[ ]".to_string()
                } else {
