impl Stmt {
    pub fn to_ast_string_inline(&self) -> String {
        match self {
            Stmt::Expr(expr) => expr.to_ast_string_inline(),
            _ => self.to_ast_string(0),
        }
    }

    pub fn to_ast_string(&self, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match self {
            Stmt::Let { name, init, .. } => match init {
                Some(expr) => format!("{}let {} = {}", ind, name, expr.to_ast_string(indent)),
                None => format!("{}let {} = nil", ind, name),
            },
            Stmt::Assign { target, value, .. } => {
                let tgt_str = match target {
                    AssignTarget::Var(n, _) => n.clone(),
                    AssignTarget::Field { object, field, .. } => format!("{}.{}", object.to_ast_string_inline(), field),
                    AssignTarget::Index { object, index, .. } => format!("{}[{}]", object.to_ast_string_inline(), index.to_ast_string_inline()),
                };
                format!("{}{} = {}", ind, tgt_str, value.to_ast_string(indent))
            }
            Stmt::If { cond, then_block, else_block, .. } => {
                let mut s = format!("{}if {} then\n", ind, cond.to_ast_string(indent));
                for stmt in then_block {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                if let Some(eb) = else_block {
                    s.push_str(&format!("{}else\n", ind));
                    for stmt in eb {
                        s.push_str(&stmt.to_ast_string(indent + 1));
                        s.push('\n');
                    }
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::While { cond, body, .. } => {
                let mut s = format!("{}while {} do\n", ind, cond.to_ast_string(indent));
                for stmt in body {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::For { var, iter, body, .. } => {
                let mut s = format!("{}for {} in {} do\n", ind, var, iter.to_ast_string(indent));
                for stmt in body {
                    s.push_str(&stmt.to_ast_string(indent + 1));
                    s.push('\n');
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::Break(_) => format!("{}break", ind),
            Stmt::Return(opt_expr, _) => match opt_expr {
                Some(expr) => format!("{}return {}", ind, expr.to_ast_string(indent)),
                None => format!("{}return nil", ind),
            },
            Stmt::Expr(expr) => format!("{}{}", ind, expr.to_ast_string(indent)),
        }
    }
}

impl CommandBlock {
    pub fn to_ast_string(&self, indent: usize, prefix: &str) -> String {
        let ind = "\t".repeat(indent);
        let mut s = format!("{}{{\n", prefix);
        for (i, pipe) in self.pipelines.iter().enumerate() {
            s.push_str(&format!("{}\t", ind));
            let mut pipe_cmds = Vec::new();
            for cmd in &pipe.commands {
                let mut cmd_str = Vec::new();
                for arg in &cmd.args {
                    cmd_str.push(arg.to_ast_string(indent + 1));
                }
                for r in &cmd.redirections {
                    match r {
                        Redirection::In(e) => cmd_str.push(format!("<{}", e.to_ast_string(indent + 1))),
                        Redirection::Out(e) => cmd_str.push(format!("1>{}", e.to_ast_string(indent + 1))),
                        Redirection::Append(e) => cmd_str.push(format!("1>>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrOut(e) => cmd_str.push(format!("2>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrAppend(e) => cmd_str.push(format!("2>>{}", e.to_ast_string(indent + 1))),
                        Redirection::ErrToOut => cmd_str.push("2>1".to_string()),
                        Redirection::OutToErr => cmd_str.push("1>2".to_string()),
                        Redirection::HereString(e) => cmd_str.push(format!("<<{}", e.to_ast_string(indent + 1))),
                    }
                }
                if cmd.try_op {
                    cmd_str.push("?".to_string());
                }
                pipe_cmds.push(cmd_str.join(" "));
            }
            s.push_str(&pipe_cmds.join(" | "));
            if i + 1 < self.pipelines.len() {
                s.push_str(";\n");
            } else {
                s.push('\n');
            }
        }
        s.push_str(&format!("{}}}", ind));
        s
    }
}
