cat << 'EOF' > src/parser.rs
use crate::lexer::{Token, TokenKind};
use crate::ast::*;

#[derive(Debug, Clone)]
pub struct ParseError {
    pub line: usize,
    pub column: usize,
    pub message: String,
}

pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    pub errors: Vec<ParseError>,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self {
            tokens,
            pos: 0,
            errors: Vec::new(),
        }
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn peek_nth(&self, n: usize) -> Option<&Token> {
        self.tokens.get(self.pos + n)
    }

    fn advance(&mut self) -> Option<&Token> {
        if self.pos < self.tokens.len() {
            let tok = &self.tokens[self.pos];
            self.pos += 1;
            Some(tok)
        } else {
            None
        }
    }

    fn match_kind(&mut self, kind: &TokenKind) -> bool {
        if let Some(tok) = self.peek() {
            if std::mem::discriminant(&tok.kind) == std::mem::discriminant(kind) {
                self.advance();
                return true;
            }
        }
        false
    }

    fn expect(&mut self, kind: &TokenKind, expected_desc: &str) -> Result<&Token, ParseError> {
        if let Some(tok) = self.peek() {
            if std::mem::discriminant(&tok.kind) == std::mem::discriminant(kind) {
                Ok(self.advance().unwrap())
            } else {
                Err(ParseError {
                    line: tok.line,
                    column: tok.column,
                    message: format!("unexpected '{}', expected {}", tok.text, expected_desc),
                })
            }
        } else {
            Err(ParseError {
                line: 0,
                column: 0,
                message: "unexpected end of file".to_string(),
            })
        }
    }

    pub fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while self.peek().is_some() {
            if self.match_kind(&TokenKind::Semicolon) {
                continue;
            }
            match self.parse_stmt() {
                Ok(stmt) => stmts.push(stmt),
                Err(err) => {
                    self.errors.push(err);
                    self.advance(); // recover
                }
            }
        }
        stmts
    }

    fn parse_stmt(&mut self) -> Result<Stmt, ParseError> {
        let tok = match self.peek() {
            Some(t) => t.clone(),
            None => return Err(ParseError { line: 0, column: 0, message: "unexpected end of file".to_string() }),
        };
        let loc = Loc { line: tok.line, column: tok.column };

        match &tok.kind {
            TokenKind::Let => self.parse_let_stmt(loc),
            TokenKind::Function => {
                if let Some(next) = self.peek_nth(1) {
                    if let TokenKind::Ident(name) = &next.kind {
                        let name = name.clone();
                        let name_tok = next.clone();
                        let name_loc = Loc { line: name_tok.line, column: name_tok.column };
                        self.advance(); // consume function
                        self.advance(); // consume name
                        let (params, body) = self.parse_func_params_and_body(loc.clone())?;
                        return Ok(Stmt::Let {
                            name,
                            init: Some(Expr::Func { params, body, loc: loc.clone() }),
                            loc,
                        });
                    }
                }
                let expr = self.parse_expr(0)?;
                Ok(Stmt::Expr(expr))
            }
            TokenKind::If => {
                let expr = self.parse_if_expr()?;
                Ok(Stmt::Expr(expr))
            }
            TokenKind::While => self.parse_while_stmt(loc),
            TokenKind::For => self.parse_for_stmt(loc),
            TokenKind::Break => {
                self.advance();
                Ok(Stmt::Break(loc))
            }
            TokenKind::Return => {
                self.advance();
                if let Some(t) = self.peek() {
                    if matches!(t.kind, TokenKind::End | TokenKind::Else | TokenKind::Semicolon | TokenKind::RBrace) {
                        return Ok(Stmt::Return(None, loc));
                    }
                } else {
                    return Ok(Stmt::Return(None, loc));
                }
                let expr = self.parse_expr(0)?;
                Ok(Stmt::Return(Some(expr), loc))
            }
            _ => {
                let expr = self.parse_expr(0)?;
                if self.peek().map_or(false, |t| matches!(t.kind, TokenKind::Assign)) {
                    self.advance(); // consume =
                    let val = self.parse_expr(0)?;
                    let target = match expr {
                        Expr::Var(n, l) => AssignTarget::Var(n, l),
                        Expr::Field { object, field, loc: l } => AssignTarget::Field { object, field, loc: l },
                        Expr::Index { object, index, loc: l } => AssignTarget::Index { object, index, loc: l },
                        _ => return Err(ParseError { line: tok.line, column: tok.column, message: "invalid assignment target".to_string() }),
                    };
                    Ok(Stmt::Assign { target, value: val, loc })
                } else {
                    Ok(Stmt::Expr(expr))
                }
            }
        }
    }

    fn parse_let_stmt(&mut self, loc: Loc) -> Result<Stmt, ParseError> {
        self.advance(); // consume let
        let name_tok = self.expect(&TokenKind::Ident(String::new()), "identifier")?.clone();
        let name = match name_tok.kind {
            TokenKind::Ident(n) => n,
            _ => unreachable!(),
        };

        let init = if self.match_kind(&TokenKind::Assign) {
            Some(self.parse_expr(0)?)
        } else {
            None
        };

        Ok(Stmt::Let { name, init, loc })
    }

    fn parse_while_stmt(&mut self, loc: Loc) -> Result<Stmt, ParseError> {
        self.advance(); // consume while
        let cond = self.parse_expr(0)?;
        self.expect(&TokenKind::Do, "'do'")?;
        let mut body = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::End)) {
            if self.match_kind(&TokenKind::Semicolon) { continue; }
            body.push(self.parse_stmt()?);
        }
        self.expect(&TokenKind::End, "'end'")?;
        Ok(Stmt::While { cond, body, loc })
    }

    fn parse_for_stmt(&mut self, loc: Loc) -> Result<Stmt, ParseError> {
        self.advance(); // consume for
        let var_tok = self.expect(&TokenKind::Ident(String::new()), "identifier")?.clone();
        let var_loc = Loc { line: var_tok.line, column: var_tok.column };
        let var = match var_tok.kind { TokenKind::Ident(n) => n, _ => unreachable!() };
        self.expect(&TokenKind::In, "'in'")?;
        let iter = self.parse_expr(0)?;
        self.expect(&TokenKind::Do, "'do'")?;
        let mut body = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::End)) {
            if self.match_kind(&TokenKind::Semicolon) { continue; }
            body.push(self.parse_stmt()?);
        }
        self.expect(&TokenKind::End, "'end'")?;
        Ok(Stmt::For { var, var_loc, iter, body, loc })
    }

    fn parse_func_params_and_body(&mut self, loc: Loc) -> Result<(Vec<(String, Loc)>, Vec<Stmt>), ParseError> {
        self.expect(&TokenKind::LParen, "'('")?;
        let mut params = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RParen)) {
            let p_tok = self.expect(&TokenKind::Ident(String::new()), "identifier")?.clone();
            let p_loc = Loc { line: p_tok.line, column: p_tok.column };
            if let TokenKind::Ident(p) = p_tok.kind {
                params.push((p, p_loc));
            }
            if !self.match_kind(&TokenKind::Comma) {
                break;
            }
        }
        self.expect(&TokenKind::RParen, "')'")?;

        let mut body = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::End)) {
            if self.match_kind(&TokenKind::Semicolon) { continue; }
            body.push(self.parse_stmt()?);
        }
        self.expect(&TokenKind::End, "'end'")?;

        Ok((params, body))
    }

    fn parse_if_expr(&mut self) -> Result<Expr, ParseError> {
        let tok = self.peek().unwrap().clone();
        let loc = Loc { line: tok.line, column: tok.column };
        self.advance(); // consume if
        let cond = Box::new(self.parse_expr(0)?);
        self.expect(&TokenKind::Then, "'then'")?;
        let mut then_block = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::Else | TokenKind::End)) {
            if self.match_kind(&TokenKind::Semicolon) { continue; }
            then_block.push(self.parse_stmt()?);
        }

        let else_block = if self.match_kind(&TokenKind::Else) {
            let mut eb = Vec::new();
            while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::End)) {
                if self.match_kind(&TokenKind::Semicolon) { continue; }
                eb.push(self.parse_stmt()?);
            }
            Some(eb)
        } else {
            None
        };

        self.expect(&TokenKind::End, "'end'")?;

        Ok(Expr::If { cond, then_block, else_block, loc })
    }

    pub fn parse_expr(&mut self, min_prec: u8) -> Result<Expr, ParseError> {
        let mut left = self.parse_primary()?;

        loop {
            if self.match_kind(&TokenKind::LParen) {
                let loc = left.loc();
                let mut args = Vec::new();
                while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RParen)) {
                    args.push(self.parse_expr(0)?);
                    if !self.match_kind(&TokenKind::Comma) { break; }
                }
                self.expect(&TokenKind::RParen, "')'")?;
                left = Expr::Call { callee: Box::new(left), args, loc };
                continue;
            }

            if self.match_kind(&TokenKind::Dot) {
                let field_tok = self.expect(&TokenKind::Ident(String::new()), "identifier")?.clone();
                let field = match field_tok.kind { TokenKind::Ident(f) => f, _ => unreachable!() };
                let loc = left.loc();
                if self.peek().map_or(false, |t| matches!(t.kind, TokenKind::LParen)) {
                    self.advance(); // consume (
                    let mut args = Vec::new();
                    while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RParen)) {
                        args.push(self.parse_expr(0)?);
                        if !self.match_kind(&TokenKind::Comma) { break; }
                    }
                    self.expect(&TokenKind::RParen, "')'")?;
                    left = Expr::MethodCall { object: Box::new(left), method: field, args, loc };
                } else {
                    left = Expr::Field { object: Box::new(left), field, loc };
                }
                continue;
            }

            if self.match_kind(&TokenKind::LBracket) {
                let loc = left.loc();
                let index = self.parse_expr(0)?;
                self.expect(&TokenKind::RBracket, "']'")?;
                left = Expr::Index { object: Box::new(left), index: Box::new(index), loc };
                continue;
            }

            if self.match_kind(&TokenKind::Question) {
                let loc = left.loc();
                left = Expr::Unary { op: UnaryOp::Try, expr: Box::new(left), loc };
                continue;
            }

            let tok = match self.peek() {
                Some(t) => t,
                None => break,
            };

            let (op, prec, right_assoc) = match &tok.kind {
                TokenKind::Or => (BinaryOp::Or, 1, false),
                TokenKind::And => (BinaryOp::And, 2, false),
                TokenKind::Eq => (BinaryOp::Eq, 3, false),
                TokenKind::NotEq => (BinaryOp::NotEq, 3, false),
                TokenKind::Lt => (BinaryOp::Lt, 3, false),
                TokenKind::LtEq => (BinaryOp::LtEq, 3, false),
                TokenKind::Gt => (BinaryOp::Gt, 3, false),
                TokenKind::GtEq => (BinaryOp::GtEq, 3, false),
                TokenKind::Concat => (BinaryOp::Concat, 4, false),
                TokenKind::Plus => (BinaryOp::Add, 5, false),
                TokenKind::Minus => (BinaryOp::Sub, 5, false),
                TokenKind::Star => (BinaryOp::Mul, 6, false),
                TokenKind::Slash => (BinaryOp::Div, 6, false),
                TokenKind::Percent => (BinaryOp::Mod, 6, false),
                _ => break,
            };

            if prec < min_prec {
                break;
            }

            self.advance(); // consume operator
            let loc = left.loc();
            let next_prec = if right_assoc { prec } else { prec + 1 };
            let right = self.parse_expr(next_prec)?;
            left = Expr::Binary { op, left: Box::new(left), right: Box::new(right), loc };
        }

        Ok(left)
    }

    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        let tok = match self.peek() {
            Some(t) => t.clone(),
            None => return Err(ParseError { line: 0, column: 0, message: "unexpected end of file".to_string() }),
        };
        let loc = Loc { line: tok.line, column: tok.column };

        match &tok.kind {
            TokenKind::Nil => { self.advance(); Ok(Expr::Literal(LiteralValue::Nil, loc)) }
            TokenKind::True => { self.advance(); Ok(Expr::Literal(LiteralValue::Bool(true), loc)) }
            TokenKind::False => { self.advance(); Ok(Expr::Literal(LiteralValue::Bool(false), loc)) }
            TokenKind::Int(i) => { let val = *i; self.advance(); Ok(Expr::Literal(LiteralValue::Int(val), loc)) }
            TokenKind::Float(f) => { let val = *f; self.advance(); Ok(Expr::Literal(LiteralValue::Float(val), loc)) }
            TokenKind::Char(c) => { let val = *c; self.advance(); Ok(Expr::Literal(LiteralValue::Char(val), loc)) }
            TokenKind::StringLit(s) => { let val = s.clone(); self.advance(); Ok(Expr::Literal(LiteralValue::String(val), loc)) }
            TokenKind::Ident(name) => { let val = name.clone(); self.advance(); Ok(Expr::Var(val, loc)) }
            TokenKind::SelfKw => { self.advance(); Ok(Expr::SelfKw(loc)) }
            TokenKind::LParen => {
                self.advance(); // consume (
                let expr = self.parse_expr(0)?;
                self.expect(&TokenKind::RParen, "')'")?;
                Ok(expr)
            }
            TokenKind::LBracket => {
                self.advance(); // consume [
                let mut items = Vec::new();
                while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RBracket)) {
                    items.push(self.parse_expr(0)?);
                    if !self.match_kind(&TokenKind::Comma) { break; }
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Expr::Array(items, loc))
            }
            TokenKind::DictOpen => {
                self.advance(); // consume @[
                let mut entries = Vec::new();
                while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RBracket)) {
                    let k_tok = self.expect(&TokenKind::Ident(String::new()), "identifier")?.clone();
                    let key = match k_tok.kind { TokenKind::Ident(k) => k, _ => unreachable!() };
                    self.expect(&TokenKind::Colon, "':'")?;
                    let val = self.parse_expr(0)?;
                    entries.push((key, val));
                    if !self.match_kind(&TokenKind::Comma) { break; }
                }
                self.expect(&TokenKind::RBracket, "']'")?;
                Ok(Expr::Dict(entries, loc))
            }
            TokenKind::Function => {
                self.advance(); // consume function
                let (params, body) = self.parse_func_params_and_body(loc.clone())?;
                Ok(Expr::Func { params, body, loc })
            }
            TokenKind::If => self.parse_if_expr(),
            TokenKind::Minus => {
                self.advance();
                let expr = self.parse_expr(7)?;
                Ok(Expr::Unary { op: UnaryOp::Neg, expr: Box::new(expr), loc })
            }
            TokenKind::Not => {
                self.advance();
                let expr = self.parse_expr(7)?;
                Ok(Expr::Unary { op: UnaryOp::Not, expr: Box::new(expr), loc })
            }
            TokenKind::LBrace => {
                self.advance();
                let cb = self.parse_command_block(loc)?;
                Ok(Expr::Command(cb))
            }
            TokenKind::TryBrace => {
                self.advance();
                let cb = self.parse_command_block(loc)?;
                Ok(Expr::CaptureCommand(cb))
            }
            TokenKind::AsyncBrace => {
                self.advance();
                let cb = self.parse_command_block(loc)?;
                Ok(Expr::AsyncCommand(cb))
            }
            _ => Err(ParseError {
                line: tok.line,
                column: tok.column,
                message: format!("unexpected '{}', expected expression", tok.text),
            }),
        }
    }

    fn parse_command_block(&mut self, loc: Loc) -> Result<CommandBlock, ParseError> {
        let mut pipelines = Vec::new();
        while self.peek().map_or(false, |t| !matches!(t.kind, TokenKind::RBrace)) {
            if self.match_kind(&TokenKind::Semicolon) { continue; }
            let mut commands = Vec::new();
            loop {
                let cmd = self.parse_command()?;
                commands.push(cmd);
                if !self.match_kind(&TokenKind::Pipe) { break; }
            }
            pipelines.push(Pipeline { commands });
            if self.match_kind(&TokenKind::Semicolon) {
                continue;
            }
        }
        self.expect(&TokenKind::RBrace, "'}'")?;
        Ok(CommandBlock { pipelines, loc })
    }

    fn parse_command(&mut self) -> Result<Command, ParseError> {
        let mut args = Vec::new();
        let mut redirections = Vec::new();
        let mut try_op = false;
        let tok = self.peek().unwrap().clone();
        let loc = Loc { line: tok.line, column: tok.column };

        while let Some(tok) = self.peek() {
            match &tok.kind {
                TokenKind::RBrace | TokenKind::Pipe | TokenKind::Semicolon => break,
                TokenKind::Question => {
                    self.advance();
                    try_op = true;
                    break;
                }
                TokenKind::RedirectIn => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::In(arg));
                }
                TokenKind::RedirectOut => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::Out(arg));
                }
                TokenKind::RedirectAppend => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::Append(arg));
                }
                TokenKind::RedirectErr => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::ErrOut(arg));
                }
                TokenKind::RedirectErrAppend => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::ErrAppend(arg));
                }
                TokenKind::RedirectErrToOut => {
                    self.advance();
                    redirections.push(Redirection::ErrToOut);
                }
                TokenKind::RedirectOutToErr => {
                    self.advance();
                    redirections.push(Redirection::OutToErr);
                }
                TokenKind::HereString => {
                    self.advance();
                    let arg = self.parse_cmd_arg()?;
                    redirections.push(Redirection::HereString(arg));
                }
                _ => {
                    let arg = self.parse_cmd_arg()?;
                    args.push(arg);
                }
            }
        }

        Ok(Command { args, redirections, try_op, loc })
    }

    fn parse_cmd_arg(&mut self) -> Result<Expr, ParseError> {
        let tok = self.advance().ok_or_else(|| ParseError {
            line: 0, column: 0, message: "unexpected end of file".to_string()
        })?.clone();
        let loc = Loc { line: tok.line, column: tok.column };

        match &tok.kind {
            TokenKind::CmdArg(s) => Ok(Expr::Literal(LiteralValue::String(s.clone()), loc)),
            TokenKind::CmdInterp(v) => Ok(Expr::Var(v.clone(), loc)),
            TokenKind::Ident(s) => Ok(Expr::Literal(LiteralValue::String(s.clone()), loc)),
            TokenKind::StringLit(s) => Ok(Expr::Literal(LiteralValue::String(s.clone()), loc)),
            _ => Ok(Expr::Literal(LiteralValue::String(tok.text), loc)),
        }
    }
}
