        match stmt {
            Stmt::Let { name, init, loc } => {
                if matches!(init, Some(Expr::Func { .. })) {
                    self.declare_var(name, loc.clone());
                    if let Some(expr) = init {
                        self.analyze_expr(expr);
                    }
