                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::Break(_) => format!("{}break", ind),
            Stmt::Return(opt_expr, _) => match opt_expr {
                Some(e) => format!("{}return {}", ind, self.format_expr(e)),
                None => format!("{}return nil", ind),
            },
            Stmt::Expr(expr) => format!("{}{}", ind, self.format_expr(expr)),
        }
    }
}

impl CommandBlock {
    pub fn to_ir_string(&self, gen: &mut ProgramIrGenerator) -> String {
        let mut s = "{\n".to_string();
        for (i, pipe) in self.pipelines.iter().enumerate() {
            s.push_str("\t");
            let mut pipe_cmds = Vec::new();
            for cmd in &pipe.commands {
                let mut cmd_str = Vec::new();
                for arg in &cmd.args {
                    cmd_str.push(gen.format_expr(arg));
                }
                for r in &cmd.redirections {
                    match r {
                        Redirection::In(e) => cmd_str.push(format!("<{}", gen.format_expr(e))),
                        Redirection::Out(e) => cmd_str.push(format!("1>{}", gen.format_expr(e))),
                        Redirection::Append(e) => cmd_str.push(format!("1>>{}", gen.format_expr(e))),
                        Redirection::ErrOut(e) => cmd_str.push(format!("2>{}", gen.format_expr(e))),
                        Redirection::ErrAppend(e) => cmd_str.push(format!("2>>{}", gen.format_expr(e))),
                        Redirection::ErrToOut => cmd_str.push("2>1".to_string()),
                        Redirection::OutToErr => cmd_str.push("1>2".to_string()),
                        Redirection::HereString(e) => cmd_str.push(format!("<<{}", gen.format_expr(e))),
                    }
                }
                if cmd.try_op {
                    cmd_str.push("?".to_string());
                }
                pipe_cmds.push(cmd_str.join(" "));
            }
            s.push_str(&pipe_cmds.join(" | "));
            if i + 1 < self.pipelines.len() {
                s.push_str(";\n");
            } else {
                s.push('\n');
            }
        }
        s.push_str("}");
        s
    }
}
