use std::collections::HashMap;
use crate::ast::*;

pub struct ProgramIrGenerator {
    next_reg: usize,
    var_map: HashMap<String, usize>,
}

impl ProgramIrGenerator {
    pub fn new() -> Self {
        let mut var_map = HashMap::new();
        var_map.insert("std".to_string(), 0);
        Self {
            next_reg: 1,
            var_map,
        }
    }

    fn alloc_reg_for_var(&mut self, name: &str) -> usize {
        if let Some(&r) = self.var_map.get(name) {
            r
        } else {
            let r = self.next_reg;
            self.next_reg += 1;
            self.var_map.insert(name.to_string(), r);
            r
        }
    }

