                format!("{}.{}", self.format_expr(object, indent), field)
            }
            Expr::MethodCall { object, method, args, .. } => {
                let arg_strs: Vec<String> = args.iter().map(|a| self.format_expr(a, indent)).collect();
                format!("{}.{}({})", self.format_expr(object, indent), method, arg_strs.join(", "))
            }
            Expr::Index { object, index, .. } => {
                format!("{}[{}]", self.format_expr(object, indent), self.format_expr(index, indent))
            }
            Expr::If { cond, then_block, else_block, .. } => {
