            Expr::CaptureCommand(cmd) => format!("${}", cmd.to_ir_string(self, indent)),
            Expr::AsyncCommand(cmd) => format!("&{}", cmd.to_ir_string(self, indent)),
        }
    }

    fn format_stmt(&mut self, stmt: &Stmt, indent: usize) -> String {
        let ind = "\t".repeat(indent);
        match stmt {
            Stmt::Let { name, init, .. } => {
                let reg = self.alloc_reg_for_var(name);
                match init {
                    Some(e) => format!("{}#{} = {}", ind, reg, self.format_expr(e, indent)),
                    None => format!("{}#{} = nil", ind, reg),
                }
            }
            Stmt::Assign { target, value, .. } => {
                let tgt_str = match target {
                    AssignTarget::Var(n, _) => format!("#{}", self.alloc_reg_for_var(n)),
                    AssignTarget::Field { object, field, .. } => format!("{}[{}]", self.format_expr(object, indent), field),
                    AssignTarget::Index { object, index, .. } => format!("{}[{}]", self.format_expr(object, indent), self.format_expr(index, indent)),
                };
                format!("{}{} = {}", ind, tgt_str, self.format_expr(value, indent))
            }
            Stmt::If { cond, then_block, else_block, .. } => {
                let mut s = format!("{}if {} then\n", ind, self.format_expr(cond, indent));
                for stmt in then_block {
                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                if let Some(eb) = else_block {
                    s.push_str(&format!("{}else\n", ind));
                    for stmt in eb {
                        s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                    }
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::While { cond, body, .. } => {
                let mut s = format!("{}while {} do\n", ind, self.format_expr(cond, indent));
                for stmt in body {
                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::For { var, iter, body, .. } => {
                let reg = self.alloc_reg_for_var(var);
                let mut s = format!("{}for #{} in {} do\n", ind, reg, self.format_expr(iter, indent));
                for stmt in body {
                    s.push_str(&format!("{}\n", self.format_stmt(stmt, indent + 1)));
                }
                s.push_str(&format!("{}end", ind));
                s
            }
            Stmt::Break(_) => format!("{}break", ind),
            Stmt::Return(opt_expr, _) => match opt_expr {
                Some(e) => format!("{}return {}", ind, self.format_expr(e, indent)),
                None => format!("{}return nil", ind),
            },
            Stmt::Expr(expr) => format!("{}{}", ind, self.format_expr(expr, indent)),
        }
    }
}

impl CommandBlock {
    pub fn to_ir_string(&self, gen: &mut ProgramIrGenerator, indent: usize) -> String {
        let mut s = "{\n".to_string();
        let ind = "\t".repeat(indent);
        for (i, pipe) in self.pipelines.iter().enumerate() {
            s.push_str(&format!("{}\t", ind));
            let mut pipe_cmds = Vec::new();
            for cmd in &pipe.commands {
                let mut cmd_str = Vec::new();
                for arg in &cmd.args {
                    cmd_str.push(gen.format_expr(arg, indent + 1));
                }
                for r in &cmd.redirections {
                    match r {
                        Redirection::In(e) => cmd_str.push(format!("<{}", gen.format_expr(e, indent + 1))),
                        Redirection::Out(e) => cmd_str.push(format!("1>{}", gen.format_expr(e, indent + 1))),
                        Redirection::Append(e) => cmd_str.push(format!("1>>{}", gen.format_expr(e, indent + 1))),
                        Redirection::ErrOut(e) => cmd_str.push(format!("2>{}", gen.format_expr(e, indent + 1))),
                        Redirection::ErrAppend(e) => cmd_str.push(format!("2>>{}", gen.format_expr(e, indent + 1))),
                        Redirection::ErrToOut => cmd_str.push("2>1".to_string()),
                        Redirection::OutToErr => cmd_str.push("1>2".to_string()),
                        Redirection::HereString(e) => cmd_str.push(format!("<<{}", gen.format_expr(e, indent + 1))),
                    }
                }
                if cmd.try_op {
                    cmd_str.push("?".to_string());
                }
                pipe_cmds.push(cmd_str.join(" "));
            }
            s.push_str(&pipe_cmds.join(" | "));
            if i + 1 < self.pipelines.len() {
                s.push_str(";\n");
            } else {
                s.push('\n');
            }
        }
        s.push_str(&format!("{}}}", ind));
        s
    }
}
