            let kind = match s.as_str() {
                "let" => TokenKind::Let,
                "if" => TokenKind::If,
                "then" => TokenKind::Then,
                "else" => TokenKind::Else,
                "end" => TokenKind::End,
                "while" => TokenKind::While,
                "do" => TokenKind::Do,
                "for" => TokenKind::For,
                "in" => TokenKind::In,
                "break" => TokenKind::Break,
                "return" => TokenKind::Return,
                "function" => TokenKind::Function,
                "and" => TokenKind::And,
                "or" => TokenKind::Or,
                "not" => TokenKind::Not,
                "true" => TokenKind::True,
                "false" => TokenKind::False,
                "nil" => TokenKind::Nil,
                "self" => TokenKind::SelfKw,
                _ => TokenKind::Ident(s.clone()),
