        for scope in self.scopes.iter().rev() {
            if scope.contains(name) {
                return;
            }
        }
        self.errors.push(AnalysisError {
            line: loc.line,
            column: loc.column,
            message: format!("undeclared variable '{}'", name),
        });
    }

    fn check_cmd_arg_vars(&mut self, expr: &Expr) {
        match expr {
            Expr::Var(name, loc) => self.check_var(name, loc.clone()),
            Expr::Literal(LiteralValue::String(s), loc) => {
                let mut rest = s.as_str();
                while let Some(start) = rest.find("${{") {
                    if let Some(end) = rest[start + 3..].find("}}") {
                        let var_name = &rest[start + 3..start + 3 + end];
                        self.check_var(var_name, loc.clone());
                        rest = &rest[start + 3 + end + 2..];
                    } else {
                        break;
                    }
                }
            }
            _ => self.analyze_expr(expr),
        }
    }

    pub fn analyze_program(&mut self, stmts: &[Stmt]) {
        for stmt in stmts {
            self.analyze_stmt(stmt);
        }
    }

