use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;
use crate::ast::*;
use crate::value::Value;
use crate::stdlib::make_std_lib;

fn expand_cmd_glob(arg: &str) -> Vec<String> {
    let mut expanded = arg.to_string();
    if expanded.starts_with("~/") || expanded == "~" {
        if let Ok(home) = std::env::var("HOME") {
            expanded = format!("{}{}", home, &expanded[1..]);
        }
    }
    if !expanded.contains('*') && !expanded.contains('?') {
        return vec![expanded];
    }
    let (dir_path, pattern) = if let Some(last_slash) = expanded.rfind('/') {
        (&expanded[..last_slash + 1], &expanded[last_slash + 1..])
    } else {
        ("", expanded.as_str())
    };
    let read_dir = if dir_path.is_empty() { "." } else { dir_path };
    let mut matches = Vec::new();
    if let Ok(entries) = std::fs::read_dir(read_dir) {
        for entry in entries.flatten() {
            if let Ok(name) = entry.file_name().into_string() {
                if glob_match(pattern, &name) {
                    matches.push(format!("{}{}", dir_path, name));
                }
            }
        }
    }
    if matches.is_empty() {
        vec![expanded]
    } else {
        matches.sort();
        matches
    }
}

fn glob_match(pattern: &str, name: &str) -> bool {
    let pat_chars: Vec<char> = pattern.chars().collect();
    let name_chars: Vec<char> = name.chars().collect();
    let mut px = 0;
    let mut nx = 0;
    let mut next_px = 0;
    let mut next_nx = 0;
    while px < pat_chars.len() || nx < name_chars.len() {
        if px < pat_chars.len() {
            let c = pat_chars[px];
            match c {
                '?' => {
                    if nx < name_chars.len() {
                        px += 1;
                        nx += 1;
                        continue;
                    }
                }
                '*' => {
                    next_px = px;
                    next_nx = nx + 1;
                    px += 1;
                    continue;
                }
                _ => {
                    if nx < name_chars.len() && name_chars[nx] == c {
                        px += 1;
                        nx += 1;
                        continue;
                    }
                }
            }
        }
        if 0 < next_nx && next_nx <= name_chars.len() {
            px = next_px;
            nx = next_nx;
            continue;
        }
        return false;
    }
    true
}

#[derive(Debug, Clone)]
pub struct EvalError {
    pub loc: Loc,
    pub message: String,
}

#[derive(Clone)]
pub struct Env {
    pub vars: HashMap<String, Value>,
}

impl Env {
    pub fn new() -> Self {
        Self { vars: HashMap::new() }
    }
}

pub struct Evaluator {
    pub filename: String,
    pub env_stack: Vec<Env>,
    pub current_self: Option<Value>,
}

impl Evaluator {
    pub fn new(filename: String, args: Vec<String>) -> Self {
        let mut global_env = Env::new();
        let std_dict = Value::Dict(Rc::new(RefCell::new(make_std_lib(args))));
        global_env.vars.insert("std".to_string(), std_dict);

        Self {
            filename,
            env_stack: vec![global_env],
            current_self: None,
        }
    }

    fn push_env(&mut self) {
        self.env_stack.push(Env::new());
    }

    fn pop_env(&mut self) {
        self.env_stack.pop();
    }

    pub fn get_var(&self, name: &str) -> Option<Value> {
        for env in self.env_stack.iter().rev() {
            if let Some(val) = env.vars.get(name) {
                return Some(val.clone());
            }
        }
        None
    }

    pub fn set_var(&mut self, name: &str, val: Value) {
        for env in self.env_stack.iter_mut().rev() {
            if env.vars.contains_key(name) {
                env.vars.insert(name.to_string(), val);
                return;
            }
        }
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn declare_var(&mut self, name: &str, val: Value) {
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn eval_program(&mut self, stmts: &[Stmt]) -> Result<Value, EvalError> {
        let mut last_val = Value::Nil;
        for stmt in stmts {
            last_val = self.eval_stmt(stmt)?;
        }
        Ok(last_val)
    }

    pub fn eval_stmt(&mut self, stmt: &Stmt) -> Result<Value, EvalError> {
        match stmt {
            Stmt::Let { name, init, .. } => {
                let val = match init {
                    Some(expr) => self.eval_expr(expr)?,
                    None => Value::Nil,
                };
                self.declare_var(name, val);
                Ok(Value::Nil)
            }
            Stmt::Assign { target, value, loc } => {
                let val = self.eval_expr(value)?;
                match target {
                    AssignTarget::Var(name, _) => {
                        self.set_var(name, val);
                    }
                    AssignTarget::Field { object, field, .. } => {
                        let obj_val = self.eval_expr(object)?;
                        if let Value::Dict(d) = obj_val {
                            d.borrow_mut().insert(field.clone(), val);
                        } else {
                            return Err(EvalError {
                                loc: object.loc(),
                                message: format!("value ({}) has unexpected type, expected dict", obj_val.to_display_string()),
                            });
                        }
                    }
                    AssignTarget::Index { object, index, .. } => {
                        let obj_val = self.eval_expr(object)?;
                        let idx_val = self.eval_expr(index)?;
                        match (obj_val, idx_val) {
                            (Value::Array(arr), Value::Int(idx)) => {
                                let mut b = arr.borrow_mut();
                                if idx < 0 || (idx as usize) >= b.len() {
                                    return Err(EvalError {
                                        loc: index.loc(),
                                        message: format!("index ({}) out of bounds", idx),
                                    });
                                }
                                b[idx as usize] = val;
                            }
                            (Value::Dict(d), Value::String(key)) => {
                                d.borrow_mut().insert(key, val);
                            }
                            (other_obj, _) => {
                                return Err(EvalError {
                                    loc: loc.clone(),
                                    message: format!("value ({}) has unexpected type", other_obj.to_display_string()),
                                });
                            }
                        }
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::If { cond, then_block, else_block, .. } => {
                let cond_val = self.eval_expr(cond)?;
                if cond_val.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(then_block)?;
                    self.pop_env();
                    Ok(res)
                } else if let Some(eb) = else_block {
                    self.push_env();
                    let res = self.eval_program(eb)?;
                    self.pop_env();
                    Ok(res)
                } else {
                    Ok(Value::Nil)
                }
            }
            Stmt::While { cond, body, .. } => {
                while self.eval_expr(cond)?.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(body);
                    self.pop_env();
                    if let Err(err) = res {
                        if err.message == "break" {
                            break;
                        } else {
                            return Err(err);
                        }
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::For { var, iter, body, .. } => {
                let iter_val = self.eval_expr(iter)?;
                match iter_val {
                    Value::RangeIter { mut current, end, step } => {
                        while (step > 0 && current < end) || (step < 0 && current > end) {
                            self.push_env();
                            self.declare_var(var, Value::Int(current));
                            let res = self.eval_program(body);
                            self.pop_env();
                            if let Err(err) = res {
                                if err.message == "break" {
                                    break;
                                } else {
                                    return Err(err);
                                }
                            }
                            current += step;
                        }
                    }
                    Value::Function { .. } | Value::BuiltinFunc { .. } => {
                        loop {
                            let next_val = self.call_func(iter_val.clone(), vec![], iter.loc())?;
                            if let Value::Dict(d) = &next_val {
                                let map = d.borrow();
                                if let Some(Value::Bool(true)) = map.get("finished") {
                                    break;
                                }
                                let val = map.get("value").cloned().unwrap_or(Value::Nil);
                                self.push_env();
                                self.declare_var(var, val);
                                let res = self.eval_program(body);
                                self.pop_env();
                                if let Err(err) = res {
                                    if err.message == "break" {
                                        break;
                                    } else {
                                        return Err(err);
                                    }
                                }
                            } else if matches!(next_val, Value::Nil) {
                                break;
                            }
                        }
                    }
                    other => {
                        return Err(EvalError {
                            loc: iter.loc(),
                            message: format!("value ({}) has unexpected type, expected function", other.to_display_string()),
                        });
                    }
                }
                Ok(Value::Nil)
            }
            Stmt::Break(loc) => Err(EvalError { loc: loc.clone(), message: "break".to_string() }),
            Stmt::Return(opt_expr, loc) => {
                let val = match opt_expr {
                    Some(e) => self.eval_expr(e)?,
                    None => Value::Nil,
                };
                Err(EvalError { loc: loc.clone(), message: format!("return:{}", val.to_display_string()) })
            }
            Stmt::Expr(expr) => self.eval_expr(expr),
        }
    }

    pub fn eval_expr(&mut self, expr: &Expr) -> Result<Value, EvalError> {
        match expr {
            Expr::CommandArgParts(parts, _) => {
                let mut s = String::new();
                for p in parts {
                    let v = self.eval_expr(p)?;
                    s.push_str(&v.to_display_string());
                }
                Ok(Value::String(s))
            }
            Expr::Literal(val, _) => match val {
                LiteralValue::Nil => Ok(Value::Nil),
                LiteralValue::Bool(b) => Ok(Value::Bool(*b)),
                LiteralValue::Int(i) => Ok(Value::Int(*i)),
                LiteralValue::Float(f) => Ok(Value::Float(*f)),
                LiteralValue::Char(c) => Ok(Value::Char(*c)),
                LiteralValue::String(s) => Ok(Value::String(s.clone())),
            },
            Expr::Var(name, loc) => {
                if let Some(val) = self.get_var(name) {
                    Ok(val)
                } else {
                    Err(EvalError {
                        loc: loc.clone(),
                        message: format!("undeclared variable '{}'", name),
                    })
                }
            }
            Expr::SelfKw(_) => {
                if let Some(val) = &self.current_self {
                    Ok(val.clone())
                } else {
                    Ok(Value::Nil)
                }
            }
            Expr::Array(items, _) => {
                let mut evaluated = Vec::new();
                for item in items {
                    evaluated.push(self.eval_expr(item)?);
                }
                Ok(Value::Array(Rc::new(RefCell::new(evaluated))))
            }
            Expr::Dict(entries, _) => {
                let mut map = HashMap::new();
                for (k, v) in entries {
                    let eval_v = self.eval_expr(v)?;
                    map.insert(k.clone(), eval_v);
                }
                Ok(Value::Dict(Rc::new(RefCell::new(map))))
            }
            Expr::Func { params, body, loc } => {
                let mut env = HashMap::new();
                if let Some(top) = self.env_stack.last() {
                    env = top.vars.clone();
                }
                let param_names: Vec<String> = params.iter().map(|p| p.0.clone()).collect();
                Ok(Value::Function {
                    params: param_names,
                    body: body.clone(),
                    env,
                    bound_self: None,
                    loc_str: format!("{} (line {}, column {})", self.filename, loc.line, loc.column),
                })
            }
            Expr::Unary { op, expr, loc } => {
                let val = self.eval_expr(expr)?;
                match op {
                    UnaryOp::Neg => match val {
                        Value::Int(i) => Ok(Value::Int(-i)),
                        Value::Float(f) => Ok(Value::Float(-f)),
                        other => Err(EvalError {
                            loc: expr.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other.to_display_string()),
                        }),
                    },
                    UnaryOp::Not => Ok(Value::Bool(!val.is_truthy())),
                    UnaryOp::Try => match val {
                        Value::Error { message, detail } => Err(EvalError { loc: loc.clone(), message: format!("return:{}", Value::Error { message, detail }.to_display_string()) }),
                        other => Ok(other),
                    },
                }
            }
            Expr::Binary { op, left, right, loc } => {
                let l_val = self.eval_expr(left)?;
                let r_val = self.eval_expr(right)?;
                match op {
                    BinaryOp::Add => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a + b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (Value::Float(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected float", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Sub => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a - b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
