                    self.pop_env();
                    Ok(res)
                } else if let Some(eb) = else_block {
                    self.push_env();
                    let res = self.eval_program(eb)?;
                    self.pop_env();
                    Ok(res)
                } else {
                    Ok(Value::Nil)
                }
            }
