fn expand_cmd_glob(arg: &str) -> Vec<String> {
    let mut expanded = arg.to_string();
    if expanded.starts_with("~/") || expanded == "~" {
        if let Ok(home) = std::env::var("HOME") {
            expanded = format!("{}{}", home, &expanded[1..]);
        }
    }
    if !expanded.contains('*') && !expanded.contains('?') {
        return vec![expanded];
    }
    let (dir_path, pattern) = if let Some(last_slash) = expanded.rfind('/') {
        (&expanded[..last_slash + 1], &expanded[last_slash + 1..])
    } else {
        ("", expanded.as_str())
    };
    let read_dir = if dir_path.is_empty() { "." } else { dir_path };
    let mut matches = Vec::new();
    if let Ok(entries) = std::fs::read_dir(read_dir) {
        for entry in entries.flatten() {
            if let Ok(name) = entry.file_name().into_string() {
                if glob_match(pattern, &name) {
                    matches.push(format!("{}{}", dir_path, name));
                }
            }
        }
    }
    if matches.is_empty() {
        vec![expanded]
    } else {
        matches.sort();
        matches
    }
}

fn glob_match(pattern: &str, name: &str) -> bool {
    let pat_chars: Vec<char> = pattern.chars().collect();
    let name_chars: Vec<char> = name.chars().collect();
    let mut px = 0;
    let mut nx = 0;
    let mut next_px = 0;
    let mut next_nx = 0;
    while px < pat_chars.len() || nx < name_chars.len() {
        if px < pat_chars.len() {
            let c = pat_chars[px];
            match c {
                '?' => {
                    if nx < name_chars.len() {
                        px += 1;
                        nx += 1;
                        continue;
                    }
                }
                '*' => {
                    next_px = px;
                    next_nx = nx + 1;
                    px += 1;
                    continue;
                }
                _ => {
                    if nx < name_chars.len() && name_chars[nx] == c {
                        px += 1;
                        nx += 1;
                        continue;
                    }
                }
            }
        }
        if 0 < next_nx && next_nx <= name_chars.len() {
            px = next_px;
            nx = next_nx;
            continue;
        }
        return false;
    }
    true
}

#[derive(Debug, Clone)]
pub struct EvalError {
    pub loc: Loc,
    pub message: String,
}

#[derive(Clone)]
pub struct Env {
    pub vars: HashMap<String, Value>,
}

impl Env {
    pub fn new() -> Self {
        Self { vars: HashMap::new() }
    }
}

pub struct Evaluator {
    pub filename: String,
    pub env_stack: Vec<Env>,
    pub current_self: Option<Value>,
}

impl Evaluator {
    pub fn new(filename: String, args: Vec<String>) -> Self {
        let mut global_env = Env::new();
        let std_dict = Value::Dict(Rc::new(RefCell::new(make_std_lib(args))));
        global_env.vars.insert("std".to_string(), std_dict);

        Self {
            filename,
            env_stack: vec![global_env],
            current_self: None,
        }
    }

    fn push_env(&mut self) {
        self.env_stack.push(Env::new());
    }

    fn pop_env(&mut self) {
        self.env_stack.pop();
    }

    pub fn get_var(&self, name: &str) -> Option<Value> {
        for env in self.env_stack.iter().rev() {
            if let Some(val) = env.vars.get(name) {
                return Some(val.clone());
            }
        }
        None
    }

    pub fn set_var(&mut self, name: &str, val: Value) {
        for env in self.env_stack.iter_mut().rev() {
            if env.vars.contains_key(name) {
                env.vars.insert(name.to_string(), val);
                return;
            }
        }
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn declare_var(&mut self, name: &str, val: Value) {
        if let Some(top) = self.env_stack.last_mut() {
            top.vars.insert(name.to_string(), val);
        }
    }

    pub fn eval_program(&mut self, stmts: &[Stmt]) -> Result<Value, EvalError> {
        let mut last_val = Value::Nil;
        for stmt in stmts {
            last_val = self.eval_stmt(stmt)?;
        }
        Ok(last_val)
    }

    pub fn eval_stmt(&mut self, stmt: &Stmt) -> Result<Value, EvalError> {
        match stmt {
            Stmt::Let { name, init, .. } => {
                let val = match init {
                    Some(expr) => self.eval_expr(expr)?,
                    None => Value::Nil,
                };
                self.declare_var(name, val);
