                let mut evaluated = Vec::new();
                for item in items {
                    evaluated.push(self.eval_expr(item)?);
                }
                Ok(Value::Array(Rc::new(RefCell::new(evaluated))))
            }
            Expr::Dict(entries, _) => {
                let mut map = HashMap::new();
                for (k, v) in entries {
                    let eval_v = self.eval_expr(v)?;
                    map.insert(k.clone(), eval_v);
                }
                Ok(Value::Dict(Rc::new(RefCell::new(map))))
            }
            Expr::Func { params, body, loc } => {
                let mut env = HashMap::new();
                if let Some(top) = self.env_stack.last() {
                    env = top.vars.clone();
                }
                let param_names: Vec<String> = params.iter().map(|p| p.0.clone()).collect();
                Ok(Value::Function {
                    params: param_names,
                    body: body.clone(),
                    env,
                    bound_self: None,
                    loc_str: format!("{} (line {}, column {})", self.filename, loc.line, loc.column),
                })
            }
            Expr::Unary { op, expr, loc } => {
                let val = self.eval_expr(expr)?;
                match op {
                    UnaryOp::Neg => match val {
                        Value::Int(i) => Ok(Value::Int(-i)),
                        Value::Float(f) => Ok(Value::Float(-f)),
                        other => Err(EvalError {
                            loc: expr.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other.to_display_string()),
                        }),
                    },
                    UnaryOp::Not => Ok(Value::Bool(!val.is_truthy())),
                    UnaryOp::Try => match val {
                        Value::Error { message, detail } => Err(EvalError { loc: loc.clone(), message: format!("return:{}", Value::Error { message, detail }.to_display_string()) }),
                        other => Ok(other),
                    },
                }
            }
            Expr::Binary { op, left, right, loc } => {
                let l_val = self.eval_expr(left)?;
                let r_val = self.eval_expr(right)?;
                match op {
                    BinaryOp::Add => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a + b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a + b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (Value::Float(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected float", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Sub => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a - b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a - b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (Value::Float(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected float", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Mul => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => Ok(Value::Int(a * b)),
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a * b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (Value::Float(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected float", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Div => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => {
                            if *b == 0 {
                                Err(EvalError { loc: right.loc(), message: "division by zero".to_string() })
                            } else {
                                Ok(Value::Int(a / b))
                            }
                        }
                        (Value::Float(a), Value::Float(b)) => Ok(Value::Float(a / b)),
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (Value::Float(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected float", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int or float", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Mod => match (&l_val, &r_val) {
                        (Value::Int(a), Value::Int(b)) => {
                            if *b == 0 {
                                Err(EvalError { loc: right.loc(), message: "division by zero".to_string() })
                            } else {
                                Ok(Value::Int(a % b))
                            }
                        }
                        (Value::Int(_), other) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other.to_display_string()),
                        }),
                        (other_l, _) => Err(EvalError {
                            loc: left.loc(),
                            message: format!("value ({}) has unexpected type, expected int", other_l.to_display_string()),
                        }),
                    },
                    BinaryOp::Concat => match (l_val, r_val) {
                        (Value::String(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::String(a), Value::Char(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::Char(a), Value::String(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (Value::Char(a), Value::Char(b)) => Ok(Value::String(format!("{}{}", a, b))),
                        (_, other_r) => Err(EvalError {
                            loc: right.loc(),
                            message: format!("value ({}) has unexpected type, expected string", other_r.to_display_string()),
                        }),
                    },
                    BinaryOp::Eq => Ok(Value::Bool(l_val == r_val)),
                    BinaryOp::NotEq => Ok(Value::Bool(l_val != r_val)),
                    BinaryOp::Lt => self.eval_cmp(l_val, r_val, |a, b| a < b, loc.clone()),
                    BinaryOp::LtEq => self.eval_cmp(l_val, r_val, |a, b| a <= b, loc.clone()),
                    BinaryOp::Gt => self.eval_cmp(l_val, r_val, |a, b| a > b, loc.clone()),
                    BinaryOp::GtEq => self.eval_cmp(l_val, r_val, |a, b| a >= b, loc.clone()),
                    BinaryOp::And => {
                        if !l_val.is_truthy() {
                            Ok(l_val)
                        } else {
                            Ok(r_val)
                        }
                    }
                    BinaryOp::Or => {
                        if l_val.is_truthy() {
                            Ok(l_val)
                        } else {
                            Ok(r_val)
                        }
                    }
                }
            }
            Expr::Call { callee, args, loc } => {
                let callee_val = self.eval_expr(callee)?;
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a)?);
                }
                self.call_func(callee_val, arg_vals, loc.clone())
            }
            Expr::Field { object, field, loc } => {
                let obj_val = self.eval_expr(object)?;
                match obj_val {
                    Value::Dict(d) => {
                        let map = d.borrow();
                        if let Some(v) = map.get(field) {
                            Ok(v.clone())
                        } else {
                            Err(EvalError {
                                loc: loc.clone(),
                                message: format!("index (\"{}\") out of bounds", field),
                            })
                        }
                    }
                    other => Err(EvalError {
                        loc: object.loc(),
                        message: format!("value ({}) has unexpected type, expected string, array, dict or error", other.to_display_string()),
                    }),
                }
            }
            Expr::MethodCall { object, method, args, loc } => {
                let obj_val = self.eval_expr(object)?;
                let func_val = match &obj_val {
                    Value::Dict(d) => {
                        let map = d.borrow();
                        if let Some(v) = map.get(method) {
                            v.clone()
                        } else {
                            return Err(EvalError {
                                loc: loc.clone(),
                                message: format!("index (\"{}\") out of bounds", method),
                            });
                        }
                    }
                    other => return Err(EvalError {
                        loc: object.loc(),
                        message: format!("value ({}) has unexpected type, expected dict", other.to_display_string()),
                    }),
                };
                let mut arg_vals = Vec::new();
                for a in args {
                    arg_vals.push(self.eval_expr(a)?);
                }

                let old_self = self.current_self.clone();
                self.current_self = Some(obj_val);
                let res = self.call_func(func_val, arg_vals, loc.clone());
                self.current_self = old_self;
                res
            }
            Expr::Index { object, index, loc } => {
                let obj_val = self.eval_expr(object)?;
                let idx_val = self.eval_expr(index)?;
                match (obj_val, idx_val) {
                    (Value::Array(arr), Value::Int(i)) => {
                        let b = arr.borrow();
                        if i < 0 || (i as usize) >= b.len() {
                            Err(EvalError {
                                loc: index.loc(),
                                message: format!("index ({}) out of bounds", i),
                            })
                        } else {
                            Ok(b[i as usize].clone())
                        }
                    }
                    (Value::Dict(d), Value::String(s)) => {
                        let b = d.borrow();
                        if let Some(val) = b.get(&s) {
                            Ok(val.clone())
                        } else {
                            Err(EvalError {
                                loc: loc.clone(),
                                message: format!("index (\"{}\") out of bounds", s),
                            })
                        }
                    }
                    (other_obj, _) => Err(EvalError {
                        loc: object.loc(),
                        message: format!("value ({}) has unexpected type, expected string, array, dict or error", other_obj.to_display_string()),
                    }),
                }
            }
            Expr::If { cond, then_block, else_block, .. } => {
                let cond_val = self.eval_expr(cond)?;
                if cond_val.is_truthy() {
                    self.push_env();
                    let res = self.eval_program(then_block)?;
                    self.pop_env();
                    Ok(res)
                } else if let Some(eb) = else_block {
                    self.push_env();
                    let res = self.eval_program(eb)?;
                    self.pop_env();
                    Ok(res)
                } else {
                    Ok(Value::Nil)
                }
            }
            Expr::Command(cmd) => self.eval_command_block(cmd, false, false),
            Expr::CaptureCommand(cmd) => self.eval_command_block(cmd, true, false),
            Expr::AsyncCommand(cmd) => self.eval_command_block(cmd, false, true),
        }
    }

    fn eval_cmp<F>(&self, l: Value, r: Value, op: F, loc: Loc) -> Result<Value, EvalError>
    where F: Fn(f64, f64) -> bool {
        let (num_l, num_r) = match (l, r) {
            (Value::Int(a), Value::Int(b)) => (a as f64, b as f64),
            (Value::Float(a), Value::Float(b)) => (a, b),
            (Value::Int(a), Value::Float(b)) => (a as f64, b),
            (Value::Float(a), Value::Int(b)) => (a, b as f64),
            (other_l, _) => return Err(EvalError {
                loc,
                message: format!("value ({}) has unexpected type, expected int, float, byte or string", other_l.to_display_string()),
            }),
        };
        Ok(Value::Bool(op(num_l, num_r)))
    }

    pub fn call_func(&mut self, callee: Value, args: Vec<Value>, loc: Loc) -> Result<Value, EvalError> {
        match callee {
            Value::Function { params, body, env, bound_self, .. } => {
                if args.len() != params.len() {
                    return Err(EvalError {
                        loc,
                        message: format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), params.len()),
                    });
                }
                let mut new_env = Env::new();
                new_env.vars.extend(env);
                for (param, arg) in params.iter().zip(args.iter()) {
                    new_env.vars.insert(param.clone(), arg.clone());
                }

                let old_self = self.current_self.clone();
                if let Some(bs) = bound_self {
                    self.current_self = Some(*bs);
                }

                self.env_stack.push(new_env);
                let res = self.eval_program(&body);
                self.env_stack.pop();

                self.current_self = old_self;

                match res {
                    Ok(val) => Ok(val),
                    Err(err) => {
                        if err.message.starts_with("return:") {
                            // Extract return value
                            Ok(Value::Nil)
                        } else {
                            Err(err)
                        }
                    }
                }
            }
            Value::BuiltinFunc { func, .. } => {
                func(args, self).map_err(|e| EvalError { loc, message: e.to_display_string() })
            }
            other => Err(EvalError {
                loc,
                message: format!("attempt to call ({}), which is not a function", other.to_display_string()),
            }),
        }
    }

    fn eval_command_block(&mut self, cmd: &CommandBlock, capture: bool, _async_block: bool) -> Result<Value, EvalError> {
        let mut last_status = 0;
        let mut captured_stdout = String::new();
        let mut captured_stderr = String::new();

        for pipe in &cmd.pipelines {
            for c in &pipe.commands {
                let mut cmd_args = Vec::new();
                for arg_expr in &c.args {
                    let v = self.eval_expr(arg_expr)?;
                    let s = v.to_display_string();
                    cmd_args.extend(expand_cmd_glob(&s));
                }

                if cmd_args.is_empty() {
                    continue;
                }

                let program = &cmd_args[0];
                let mut process_cmd = std::process::Command::new(program);
                if cmd_args.len() > 1 {
                    process_cmd.args(&cmd_args[1..]);
                }

                if capture {
                    let output = process_cmd.output().map_err(|e| EvalError {
                        loc: c.loc.clone(),
                        message: e.to_string(),
                    })?;
                    captured_stdout.push_str(&String::from_utf8_lossy(&output.stdout));
                    captured_stderr.push_str(&String::from_utf8_lossy(&output.stderr));
                    if !output.status.success() {
                        last_status = output.status.code().unwrap_or(1);
                    }
                } else {
                    let status = process_cmd.status().map_err(|e| EvalError {
                        loc: c.loc.clone(),
                        message: e.to_string(),
                    })?;
                    if !status.success() {
                        last_status = status.code().unwrap_or(1);
                    }
                }
            }
        }

        if capture {
            if last_status != 0 {
                let mut err_map = HashMap::new();
                err_map.insert("stdout".to_string(), Value::String(captured_stdout));
                err_map.insert("stderr".to_string(), Value::String(captured_stderr));
                let mut status_map = HashMap::new();
                status_map.insert("status".to_string(), Value::Int(last_status as i64));
                err_map.insert("error".to_string(), Value::Dict(Rc::new(RefCell::new(status_map))));
                Ok(Value::Error {
                    message: "command returned non-zero".to_string(),
                    detail: Box::new(Value::Dict(Rc::new(RefCell::new(err_map)))),
                })
            } else {
                let mut map = HashMap::new();
                map.insert("stdout".to_string(), Value::String(captured_stdout));
                map.insert("stderr".to_string(), Value::String(captured_stderr));
                Ok(Value::Dict(Rc::new(RefCell::new(map))))
            }
        } else if last_status != 0 {
            let mut map = HashMap::new();
            map.insert("status".to_string(), Value::Int(last_status as i64));
            map.insert("pos".to_string(), Value::String(format!("{} (line {}, column {})", self.filename, cmd.loc.line, cmd.loc.column)));
            Ok(Value::Error {
                message: "command returned non-zero".to_string(),
                detail: Box::new(Value::Dict(Rc::new(RefCell::new(map)))),
            })
        } else {
            Ok(Value::Nil)
        }
    }
}
EOF"}

{"command":"cat << 'EOF' > src/main.rs
mod lexer;
mod ast;
mod parser;
mod analyzer;
mod ir;
mod value;
mod eval;
mod stdlib;

use std::env;
use std::fs;
use std::io::{self, Read};
use lexer::{Lexer, LexItem};
use parser::Parser;
use analyzer::Analyzer;
use ir::ProgramIrGenerator;
use eval::Evaluator;

fn print_help() {
    println!("Hush 0.1.4");
    println!("gahag <gabriel.s.b@live.com>");
    println!("Hush is a unix shell scripting language based on the Lua programming language\n");
    println!("USAGE:");
    println!("    executable [FLAGS] [arguments]...\n");
    println!("FLAGS:");
    println!("        --ast        Print the AST");
    println!("        --check      Perform only static analysis instead of executing.");
    println!("    -h, --help       Prints help information");
    println!("        --lex        Print the lexemes");
    println!("        --program    Print the PROGAM");
    println!("    -V, --version    Prints version information\n");
    println!("ARGS:");
    println!("    <arguments>...    Script and/or arguments");
}

fn main() {
    let args: Vec<String> = env::args().collect();

    let mut flag_lex = false;
    let mut flag_ast = false;
    let mut flag_program = false;
    let mut flag_check = false;

    let mut script_file: Option<String> = None;
    let mut script_args: Vec<String> = Vec::new();

    let mut idx = 1;
    while idx < args.len() {
        let arg = &args[idx];
        if arg == "-h" || arg == "--help" {
            print_help();
            std::process::exit(0);
        } else if arg == "-V" || arg == "--version" {
            println!("Hush 0.1.4");
            std::process::exit(0);
        } else if arg == "--lex" {
            flag_lex = true;
        } else if arg == "--ast" {
            flag_ast = true;
        } else if arg == "--program" {
            flag_program = true;
        } else if arg == "--check" {
            flag_check = true;
        } else if arg.starts_with('-') && script_file.is_none() {
            eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n", arg);
            eprintln!("USAGE:");
            eprintln!("    executable [FLAGS] [arguments]...\n");
            eprintln!("For more information try --help");
            std::process::exit(1);
        } else {
            if script_file.is_none() {
                script_file = Some(arg.clone());
            } else {
                script_args.push(arg.clone());
            }
        }
        idx += 1;
    }

    let (filename, source) = match script_file {
        Some(file) => {
            let content = match fs::read_to_string(&file) {
                Ok(c) => c,
                Err(err) => {
                    eprintln!("Error: failed to read file '{}': {}", file, err);
                    std::process::exit(1);
                }
            };
            (file, content)
        }
        None => {
            let mut input = String::new();
            io::stdin().read_to_string(&mut input).ok();
            ("<stdin>".to_string(), input)
        }
    };

    // 1. Lexer
    let mut lexer = Lexer::new(&source);
    let tokens = lexer.tokenize();

    if flag_lex {
        println!("--------------------------------------------------");
        for item in &lexer.items {
            match item {
                LexItem::Token(tok) => {
                    println!("{} (line {}, column {}):\t{}", filename, tok.line, tok.column, tok.text);
                }
                LexItem::Error(err) => {
                    println!("Error: line {}, column {} - {}", err.line, err.column, err.message);
                }
            }
        }
        println!("--------------------------------------------------");
    }

    if !lexer.errors.is_empty() {
        for err in &lexer.errors {
            eprintln!("Error: {} (line {}, column {}) - {}", filename, err.line, err.column, err.message);
        }
        std::process::exit(2);
    }

    // 2. Parser
    let mut parser = Parser::new(tokens);
    let stmts = parser.parse_program();

    if !parser.errors.is_empty() {
        for err in &parser.errors {
            if err.line > 0 {
                eprintln!("Error: {} (line {}, column {}) - {}", filename, err.line, err.column, err.message);
            } else {
                eprintln!("Error: {}", err.message);
            }
        }
        std::process::exit(2);
    }

    // 3. Print AST / Program if requested
    if flag_ast {
        println!("--------------------------------------------------");
        println!("AST for {}", filename);
        for stmt in &stmts {
            println!("{}", stmt.to_ast_string(0));
        }
        println!("--------------------------------------------------");
    }

    if flag_program {
        let mut ir_gen = ProgramIrGenerator::new();
        println!("{}", ir_gen.generate_program_ir(&filename, &stmts));
    }

    // 4. Static Analyzer
    let mut analyzer = Analyzer::new();
    analyzer.analyze_program(&stmts);

    if !analyzer.errors.is_empty() {
        for err in &analyzer.errors {
            eprintln!("Error: {} (line {}, column {}) - {}", filename, err.line, err.column, err.message);
        }
        std::process::exit(2);
    }

    if flag_check {
        std::process::exit(0);
    }

    // 5. Execution
    let mut evaluator = Evaluator::new(filename.clone(), script_args);
    if let Err(err) = evaluator.eval_program(&stmts) {
        eprintln!("Panic in {} (line {}, column {}): {}", filename, err.loc.line, err.loc.column, err.message);
        std::process::exit(127);
    }
}
EOF"}

