                    };
                    self.errors.push(err.clone());
                    self.items.push(LexItem::Error(err));
                    combined_text.push(next);
                    self.advance();
                }
            } else if c == '"' {
                let (_, raw) = self.lex_cmd_double_quote(line, col);
                combined_text.push_str(&raw);
            } else if c == '\'' {
                let tok = self.lex_string_single_quote(line, col);
                combined_text.push_str(&tok.text);
